async function foodSearch(){if(_foodBusy)return;const q=($('#food_q')?$('#food_q').value:'').trim();if(!q){toast('搜点啥呢');return;}
  S.food.q=q;_foodBusy=true;render();
  try{const rows=await aiGen([{role:'system',content:'你是外卖App搜索引擎，每行一个，严格用格式：餐品名:::价格数字:::店铺名:::一句描述:::一个相关emoji。生成6个相关餐品，价格合理。不要别的话。'},{role:'user',content:'搜索：'+q}],{max:700,aux:true},looseLines);
    _foodBusy=false;
    if(!rows){render();toast('搜索失败了，再试一次');return;}
    S.food.results=rows.map(p=>({name:p[0],price:+(p[1]||'').replace(/[^0-9.]/g,'')||(10+Math.floor(Math.random()*40)),shop:p[2]||'好吃外卖',desc:p[3]||'',emoji:(p[4]||'🍱').slice(0,2)}));render();
  }catch(e){_foodBusy=false;render();toast('搜索失败，再试一次');}}
function foodCart(i){const p=S.food.results[i];if(!p)return;S.food.cart.push(p);save();render();toast('已加入 🛍️');}
function foodBuy(i){const p=S.food.results[i];if(!p)return;foodDoBuy([p]);}
function openFoodCart(){const cart=S.food.cart||[];const total=cart.reduce((s,p)=>s+(+p.price),0);
  openModal(`<h3>外卖单</h3>${cart.length?cart.map((p,i)=>`<div class="bill"><div>${p.emoji||'🍱'} ${esc(p.name)}<small>${esc(p.shop||'')}</small></div><div>¥${(+p.price).toFixed(2)} <span onclick="S.food.cart.splice(${i},1);save();openFoodCart()" style="color:#fa5151;cursor:pointer;margin-left:6px">✕</span></div></div>`).join('')+`<div style="text-align:right;padding:10px 4px;font-size:16px;color:#ffb83b">合计 ¥${total.toFixed(2)}</div><div class="btns"><button class="btn p" onclick="foodDoBuy(S.food.cart.slice())">自己下单</button><button class="btn g" onclick="closeModal();foodGiftCartFlow()">🍱 全部请TA吃</button></div>${familyContacts().length?`<button class="btn g" style="margin-top:8px;background:#e8527f;color:#fff" onclick="closeModal();familyPayFlow(S.food.cart.slice())">用亲属卡付</button>`:''}`:'<div class="empty">外卖单空空的</div>'}<button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
function foodOrderRows(){return (S.me.bills||[]).filter(b=>b&&b.type==='out'&&/外卖|点了|请.+吃/.test(b.note||'')).slice().reverse().slice(0,30);}
function openFoodOrders(){const rows=foodOrderRows();openModal(`<h3>外卖订单</h3><div style="max-height:60vh;overflow:auto">${rows.length?rows.map(b=>`<div class="bill"><div style="flex:1">${esc(b.note||'外卖订单')}<small>${esc(b.time||fmtDT(b.ts||Date.now()))}</small></div><div class="neg">-¥${(+b.amount||0).toFixed(2)}</div></div>`).join(''):'<div class="empty">还没有外卖订单</div>'}</div><button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
// 一键把外卖单里的全部餐品都点给某个角色（不用一个一个点）
function foodGiftCartFlow(){const cart=(S.food.cart||[]).slice();if(!cart.length){toast('外卖单是空的');return;}window._fgcart=cart;pickTarget(foodGiftCartTo);}
function foodGiftCartTo(id){const cart=window._fgcart||[];if(!cart.length)return;const c=getC(id);if(!c)return;const total=cart.reduce((s,p)=>s+(+p.price),0);
  if(total>S.me.balance){toast('余额不够啦');return;}
  const nm=(c.remark||c.name);addBill('out',total,'请'+nm+'吃'+cart.map(p=>p.name).join('、'));
  cart.forEach(p=>pushMsg(id,{role:'user',type:'food',name:p.name,price:+p.price,shop:p.shop||'',from:'me',received:false,declined:false,id:uid()}));
  S.food.cart=[];save();closeModal();toast('一口气全点给ta啦，等ta收 🛵');
  const names=cart.map(p=>'「'+p.name+'」').join('、');
  scheduleReply(id,'[系统：'+S.me.name+'一口气给你点了'+cart.length+'份外卖：'+names+'（'+'总共¥'+total.toFixed(2)+'）。这么一大桌都是给你的，按你人设反应（惊喜/心疼ta花钱/宠溺/嫌ta乱花钱都行）。收下就单独一行 [收外卖]（收了先别说吃上了，约15分钟才送到，到了系统会提醒你再报备）；不想要就 [拒外卖]（钱原路退给ta）。整单一次处理就行。]');}
function foodDoBuy(items){if(!items.length)return;const total=items.reduce((s,p)=>s+(+p.price),0);
  if(total>S.me.balance){toast('余额不够啦');return;}
  items.forEach(p=>addBill('out',+p.price,'外卖·在'+(p.shop||'外卖')+'点了'+p.name));
  S.food.cart=S.food.cart.filter(c=>!items.includes(c));save();closeModal();render();toast('下单成功 ¥'+total.toFixed(2)+'，骑手已接单🛵');}
function foodGiftFlow(i){const p=S.food.results[i];if(!p)return;window._fgp=p;pickTarget(foodGiftTo);}
function foodGiftTo(id){const p=window._fgp;if(!p)return;if(+p.price>S.me.balance){toast('余额不够');return;}
  addBill('out',+p.price,'请'+(getC(id).remark||getC(id).name)+'吃'+p.name);
  pushMsg(id,{role:'user',type:'food',name:p.name,price:+p.price,shop:p.shop||'',from:'me',received:false,declined:false,id:uid()});
  closeModal();toast('已点给ta，等ta收 🛵');scheduleReply(id,'[系统：'+S.me.name+'给你点了外卖「'+p.name+'」。你收不收？要吃就回复里单独一行 [收外卖]（收了【先别说吃上了】，外卖要约15分钟才送到，到了系统会提醒你再报备）；不想要就 [拒外卖]（钱原路退给ta）。一张外卖卡只处理一次。]');}
// 一次处理【所有】还没处理的、她点给他的外卖卡（支持一单多份：一次[收外卖]/[拒外卖]全部搞定），返回处理到的数组
function markFood(id,mode){const ms=[...msgs(id)].filter(x=>x.role==='user'&&x.type==='food'&&x.from==='me'&&!x.received&&!x.declined);
  ms.forEach(m=>{if(mode==='reject')m.declined=true;else{m.received=true;m.deliverAt=Date.now()+900000;m.delivered=false;m.deliveryNotified=false;}});return ms;}
let _foodNotifyBusy={};
function checkFoodDelivery(){if(!isMain())return;const now=Date.now();let ch=false;
  for(const k in S.messages){const arr=S.messages[k]||[];const cid=k.split('#')[0];const c=getC(cid);
    arr.slice().forEach(m=>{
      if(m.type==='food'&&m.from==='me'&&m.received&&m.deliverAt&&now>=m.deliverAt&&(m.delivered!==true||m.deliveryNotified===false)){if(m.delivered!==true){m.delivered=true;ch=true;}if(m.deliveryNotified===false&&!_foodNotifyBusy[m.id]&&c&&!c.blocked){_foodNotifyBusy[m.id]=1;const queued=scheduleReply(cid,'[系统：你点的外卖「'+m.name+'」刚送到了、你吃上了——主动跟'+S.me.name+'报备一声（收到了、在吃、好不好吃），自然一两句。]',ok=>{delete _foodNotifyBusy[m.id];if(ok){m.deliveryNotified=true;save();}});if(!queued)delete _foodNotifyBusy[m.id];}}
      else if(m.type==='food'&&m.from==='ta'&&m.deliverAt&&!m.arrived&&!m.received&&!m.declined&&now>=m.deliverAt){m.arrived=true;ch=true;const i=arr.indexOf(m);if(i>=0)arr.splice(i,1);const sm={role:'user',type:'sys',content:'🛵 外卖「'+m.name+'」到了，签收一下~',time:Date.now(),id:uid()};arr.push(sm);arr.push(m);if(c&&!c.blocked)notifyIncoming(c,sm);}
    });}
  if(ch){save();const cu=cur();if(cu&&(cu.p==='chat'||cu.p==='wechat'))render();}}
//@@ web
setInterval(checkFoodDelivery,60000);setTimeout(checkFoodDelivery,7000);
//@@ private
setInterval(()=>northNativeBackgroundTask('food-delivery',checkFoodDelivery),60000);setTimeout(()=>northNativeBackgroundTask('food-delivery',checkFoodDelivery),7000);
