// 统一包裹配送：直接赠礼只进信箱；自购和明确代付才进入“我的订单”。
function parcelDeliver(cid,name,price,kind,opts){opts=opts||{};name=(''+(name||'商品')).slice(0,30);price=+price||0;kind=kind||'gift';const pid=uid();const arrive=Date.now()+86400000;
  S.giftbox=S.giftbox||[];S.giftbox.push({id:pid,cid:cid||null,name,price,kind,giftRecipe:opts.giftRecipe||null,buyTs:Date.now(),arriveTs:arrive,delivered:false,notified:kind==='food'?false:true});
  if(kind!=='gift'){const c=cid&&getC(cid),payerName=kind==='pay'?(opts.payerName||(c&&(c.remark||c.name))||'TA'):'';S.shop.orders=S.shop.orders||[];S.shop.orders.unshift({id:pid,cid:cid||null,name,price,shop:opts.shop||(kind==='self'?'自购':'商城'),emoji:opts.emoji||(kind==='pay'?'🛍️':'🛒'),payerName,buyTs:Date.now(),arriveTs:arrive,refunded:false,parcel:true,kind});if(S.shop.orders.length>40)S.shop.orders=S.shop.orders.slice(0,40);}}
function giftNameIsFloral(name){return /(?:花束|鲜花|玫瑰|百合|郁金香|向日葵|满天星|雏菊|牡丹|芍药|铃兰|桔梗|康乃馨|蝴蝶兰|永生花|花礼|手捧花)/i.test(String(name||''));}
function giftEffectKind(name){name=String(name||'');if(giftNameIsFloral(name))return'bouquet';if(/(?:玩偶|公仔|抱枕|小熊|熊熊|兔子|小兔|小狗|狗狗|小猫|猫猫)/i.test(name))return'teddy';if(/(?:订婚戒指|求婚戒指|钻戒|戒指|指环)/i.test(name))return'ring';return'';}
const GIFT_BOX_COLORS={blue:'#8fbce8',pink:'#f2adc7',white:'#f2efe8',red:'#ef6b6f'};
function giftBoxColor(seed){const s=String(seed||'gift');let h=0;for(let i=0;i<s.length;i++)h=(Math.imul(h,31)+s.charCodeAt(i))|0;return Object.keys(GIFT_BOX_COLORS)[Math.abs(h)%4];}
function giftBoxEnglish(kind){return kind==='bouquet'?'A BOUQUET OF FLOWERS':kind==='teddy'?'PLUSH COMPANION':kind==='ring'?'ENGAGEMENT RING':'PRIVATE GIFT';}
function giftBoxCardArt(color){return `<svg class="giftbox-mini" viewBox="0 0 180 150" aria-hidden="true" style="color:${GIFT_BOX_COLORS[color]||GIFT_BOX_COLORS.blue}"><g fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><rect x="42" y="55" width="96" height="72" rx="9"/><path d="M36 51h108v18H36zM82 51h16v76M42 94h96M87 47c-14-17-36-18-39-5-3 10 14 13 37 11M93 47c14-17 36-18 39-5 3 10-14 13-37 11"/><path d="M84 46q6-6 13 0l-2 11H86z" fill="#111116"/></g><g fill="none" stroke="currentColor" stroke-linecap="round" opacity=".75"><path d="M24 31v12M18 37h12M151 33v9M146.5 37.5h9M153 99v8M149 103h8M25 108v7M21.5 111.5h7"/></g></svg>`;}
function giftEffectRecipe(name,recipe,seed,time,words){const kind=giftEffectKind(name);if(!kind)return null;if(recipe&&recipe.type===kind){if(!recipe.boxColor)recipe.boxColor=giftBoxColor(recipe.seed||seed);return recipe;}if(typeof NorthGiftEffects==='undefined')return null;const create=kind==='bouquet'?NorthGiftEffects.createBouquetRecipe:kind==='teddy'?NorthGiftEffects.createTeddyRecipe:NorthGiftEffects.createRingRecipe;if(typeof create!=='function')return null;const made=create({giftName:name,seed:seed,time:time,words:words});made.boxColor=giftBoxColor(made.seed||seed);return made;}
function giftFlowerRecipe(name,recipe,seed,time){return giftNameIsFloral(name)?giftEffectRecipe(name,recipe,seed,time):null;}
function giftRecipeContext(recipe){if(!recipe)return'';if(recipe.type==='bouquet')return'，具体是一束「'+recipe.flowerName+'」，花语是「'+(recipe.flowerMeaning||'')+'」，赠送日期 '+(recipe.date||'');if(recipe.type==='teddy')return'，具体是「'+recipe.name+'」玩偶，附言是「'+(recipe.words||'')+'」，赠送日期 '+(recipe.date||'');if(recipe.type==='ring')return'，具体是「'+recipe.name+'」，想说的话是「'+(recipe.words||'')+'」，赠送日期 '+(recipe.date||'');return'';}
function playGiftRecipe(name,sender,recipe){const kind=giftEffectKind(name)||(recipe&&recipe.type)||'';if(kind==='bouquet'&&typeof playBouquetGiftEffect==='function')return playBouquetGiftEffect({giftName:name,sender,recipe});if(kind==='teddy'&&typeof playTeddyGiftEffect==='function')return playTeddyGiftEffect({giftName:name,sender,recipe});if(kind==='ring'&&typeof playRingGiftEffect==='function')return playRingGiftEffect({giftName:name,sender,recipe});return false;}
let _giftEffectsLoadPromise=null;
function giftEffectsReady(){return typeof playGiftBoxReveal==='function'&&typeof NorthGiftEffects!=='undefined';}
function giftEffectsEnsure(){if(giftEffectsReady())return Promise.resolve(true);if(_giftEffectsLoadPromise)return _giftEffectsLoadPromise;_giftEffectsLoadPromise=new Promise(resolve=>{let done=false;const finish=ok=>{if(done)return;done=true;clearTimeout(timer);_giftEffectsLoadPromise=null;resolve(!!ok);},script=document.createElement('script'),build=(String(APP_VER||'').match(/^v(\d+)/)||[])[1]||Date.now();script.async=true;script.src='gift-effects.js?v='+build+'&retry='+Date.now();script.onload=()=>finish(giftEffectsReady());script.onerror=()=>finish(false);const timer=setTimeout(()=>finish(false),12000);(document.head||document.documentElement).appendChild(script);});return _giftEffectsLoadPromise;}
function giftMessageFind(mid){for(const key in S.messages){const gift=(S.messages[key]||[]).find(x=>x&&x.id===mid);if(gift)return{gift,key};}return null;}
function giftMessageBloom(mid){const hit=giftMessageFind(mid),found=hit&&hit.gift;if(!found||found.from!=='ta'||!giftEffectKind(found.name))return false;
  const cid=hit.key.split('#')[0],c=getC(cid),fresh=!found.giftRecipe;found.giftRecipe=giftEffectRecipe(found.name,found.giftRecipe,found.id,found.time);if(fresh&&found.giftRecipe)save();return!!playGiftRecipe(found.name,c?(c.remark||c.name):'TA',found.giftRecipe);}
async function giftMessageOpen(mid,card){const hit=giftMessageFind(mid),found=hit&&hit.gift,kind=found&&giftEffectKind(found.name);if(!found||found.from!=='ta'||!kind)return false;if(!giftEffectsReady()&&!await giftEffectsEnsure()){toast('礼物特效还没有载入，请联网后再点一次');return false;}const fresh=!found.giftRecipe;found.giftRecipe=giftEffectRecipe(found.name,found.giftRecipe,found.id,found.time);if(fresh&&found.giftRecipe)save();if(card&&card.classList){card.classList.remove('pressed');void card.offsetWidth;card.classList.add('pressed');setTimeout(()=>card&&card.classList&&card.classList.remove('pressed'),220);}return!!playGiftBoxReveal({giftName:found.name,english:giftBoxEnglish(kind),boxColor:found.giftRecipe&&found.giftRecipe.boxColor||giftBoxColor(found.id),onOpen:()=>giftMessageBloom(mid)});}
function giftRequestIntent(text){const t=String(text||'').replace(/\s+/g,'');if(!t||/(?:不要|不想要|别送|不用送|不需要).{0,8}(?:花|礼物|玩偶|戒指|惊喜)/.test(t))return'';const flower=/(?:花花|鲜花|花束|玫瑰|百合|郁金香|向日葵|满天星|永生花)/,toy=/(?:玩偶|公仔|小熊|熊熊|兔子|小兔|小狗|狗狗|小猫|猫猫)/,ring=/(?:订婚戒指|求婚戒指|钻戒|戒指|指环)/,object=/(?:花花|鲜花|花束|花|礼物|小礼物|惊喜|玩偶|公仔|小熊|兔子|小狗|小猫|戒指|钻戒)/,ask=/(?:想要|想收|我也要|送我|给我|买给我|来一束|来束|来个|来份|有没有|能不能送|可以送|想看).{0,12}(?:花花|鲜花|花束|花|礼物|小礼物|惊喜|玩偶|公仔|小熊|兔子|小狗|小猫|戒指|钻戒)|(?:花花|礼物|小礼物|惊喜)[呀啊嘛吗呢哦～~！!。]*$/;if(!ask.test(t))return'';if(ring.test(t))return'ring';if(toy.test(t))return'teddy';if(flower.test(t)||/(?:送我|给我|想要|想收).{0,8}花/.test(t))return'bouquet';return object.test(t)?'choice':'';}
function giftRequestPrompt(text){const intent=giftRequestIntent(text);if(!intent)return'';return'\n\n# 本轮明确送礼意图（必须执行）\n'+S.me.name+'不需要说出完整的“一束鲜花”；“想要花花 / 送我花 / 想收礼物 / 有没有小惊喜”都已经是在向你要礼物。本轮不能只追问颜色、说改天买或口头答应，必须在自然回应后真正单独输出一行送礼标签。'+(intent==='bouquet'?'对方明确想要花，只能送 [送礼|一束鲜花|0|你想对ta说的话]。':intent==='teddy'?'对方明确想要玩偶，只能送 [送礼|玩偶礼物|0|你想对ta说的话]。':intent==='ring'?'对方明确提到戒指；若关系阶段适合就送 [送礼|订婚戒指|0|你想对ta说的话]，若不适合则按人设自然说明并改送花或玩偶。':'对方想收礼物但没有指定类型；请按你的人设与关系自主在鲜花、玩偶、订婚戒指中只选一种，戒指仅在关系阶段适合时选择。')+'不要解释标签、系统或随机规则。';}
function giftRequestFallback(intent){return intent==='bouquet'?'[送礼|一束鲜花|0|这束花送给你，想让你今天开心一点]':intent==='ring'?'[送礼|一束鲜花|0|先把这束花送给你，认真的承诺要留在最合适的时候]':'[送礼|玩偶礼物|0|给你一个可以抱在怀里的小惊喜]';}
const THOUGHT_EGG_COOLDOWN_MS=3*86400000;
function thoughtEggWords(value){const src=Array.isArray(value)?value:String(value||'').split(/\s*[；;／/]\s*|\r?\n+/),seen=new Set(),out=[];for(const item of src){const text=String(item||'').replace(/[\[\]【】|｜]/g,'').replace(/\s+/g,' ').trim().slice(0,24),key=text.replace(/[，。！？!?、\s]/g,'');if(!text||key.length<2||seen.has(key))continue;seen.add(key);out.push(text);if(out.length>=18)break;}return out;}
function thoughtEggHistory(c){return c&&Array.isArray(c.thoughtEggHistory)?c.thoughtEggHistory:[];}
function thoughtEggSimilarity(a,b){a=new Set(thoughtEggWords(a).map(x=>x.replace(/[，。！？!?、\s]/g,'')));b=new Set(thoughtEggWords(b).map(x=>x.replace(/[，。！？!?、\s]/g,'')));if(!a.size||!b.size)return 0;let hit=0;a.forEach(x=>{if(b.has(x))hit++;});return hit/Math.min(a.size,b.size);}
function thoughtEggCanSend(c,now){now=+now||Date.now();return !!c&&(!c.thoughtEggLastAt||now-c.thoughtEggLastAt>=THOUGHT_EGG_COOLDOWN_MS);}
function thoughtEggNovel(c,opening,thoughts,ending){const signature=[String(opening||'').trim()].concat(thoughtEggWords(thoughts),String(ending||'').trim());return !thoughtEggHistory(c).some(old=>thoughtEggSimilarity(signature,old.words||[])>=.62);}
function thoughtEggRequestIntent(text){const t=String(text||'').replace(/\s+/g,'');if(!t||/(?:不用|不要|别).{0,6}(?:说|回答|发卡片)/.test(t)||/(?:不用|不要|别|不想|不需要)(?:再)?(?:你|他|她|TA)?(?:给我)?(?:发|发送|送|来|给|打开|看).{0,6}(?:心情|心声|隐藏)?(?:彩蛋|卡片)/i.test(t))return false;return /(?:给我|让我)?(?:发|发送|送|来|给|打开|看|想看|要看|想要|要).{0,8}(?:那个|这个|一张|一个)?(?:心情|心声|隐藏)?(?:彩蛋|卡片)|(?:心情|心声|隐藏)?(?:彩蛋|卡片).{0,8}(?:给我|让我)?(?:发|发送|送|来|给|打开|看|想看|要看|想要|要)|(?:在一起|认识|陪着彼此).{0,12}(?:这么久|那么久|很久).{0,16}(?:有什么|有没有什么|有哪一些|有哪些).{0,12}(?:话|心里话).{0,12}(?:想|要).{0,5}(?:对|跟).{0,4}(?:我|咱们).{0,5}(?:说|讲)|(?:你)?(?:有什么|有没有什么).{0,10}(?:话|心里话).{0,8}(?:想|要).{0,4}(?:对|跟)我(?:说|讲)/.test(t);}
function thoughtEggRequested(c){if(!c)return false;const latest=[...(msgs(c.id)||[])].reverse().find(m=>m&&m.role==='user'&&m.type==='text');return !!(latest&&Date.now()-(+latest.time||0)<10*60000&&thoughtEggRequestIntent(latest.content));}
function thoughtEggRequestPrompt(text){if(!thoughtEggRequestIntent(text))return'';return '\n\n# 本轮隐藏心声卡为用户明确索取（必须触发）\n'+S.me.name+'问了类似“在一起这么久，你有什么话想对我说吗”，或直接要求“给我发那个心情彩蛋”。这两类说法都是隐藏心声卡的明确必触发入口，优先级高于三天自主彩蛋冷却；本轮必须按你自己的人设、你们真实经历和当前关系生成一张全新的卡，并单独输出：[心声彩蛋|一句简短开场白|16至18个不同的短句，用中文分号隔开|一句结束语]。不能只用普通文字回答，不能复用以前的卡片，也不要提系统、触发词或规则。';}
function thoughtEggPrompt(c){if(!c)return'';const left=Math.max(0,THOUGHT_EGG_COOLDOWN_MS-(Date.now()-(+c.thoughtEggLastAt||0)));if(left>0)return'\n- 【隐藏心声彩蛋暂不可自主再次发送】你已经在三天内自主发过一次隐藏心声卡。即使又发生重要的事，也先把感受自然记住、继续积累；它不因对方说“想你/爱你/给我惊喜”就触发。除非对方明确问“在一起这么久，你有什么话想对我说吗”，或直接索取“给我发那个心情/心声彩蛋”，否则本轮不要输出 [心声彩蛋]。这两类明确索取不受冷却限制；三天只是自主彩蛋的最短间隔，不是每三天必须发送。';return'\n- 【隐藏心声彩蛋·极少使用且由你自主决定】普通聊天中，它不因对方说“想你/爱你/给我惊喜”就触发；只有发生了对你们关系特别重要的事，或你连续多轮强烈思念、积累了许多具体而没说出口的话，普通消息已经装不下时，你才可以选择发送。另有两个明确入口：当对方问“在一起这么久，你有什么话想对我说吗”或同义问题，或者直接要求你发心情/心声彩蛋时，本轮必须发送。格式为：[心声彩蛋|你自己写的一句简短开场白|16至18个很短的句子，用中文分号隔开|你自己想的最后一句结束语]。每个小框只放一件事或一句心声，结合你的人设、最近真实经历、共同记忆和当下关系，禁止通用祝福。每次开场、小框内容和结尾都必须不同。自主发送时，三天只是最短间隔，不是每三天必须发送；用户明确索取不受该冷却限制。不要向对方解释彩蛋规则。';}
function thoughtEggMessage(c,rawOpening,rawThoughts,rawEnding,force){if(!c||!force&&!thoughtEggCanSend(c))return null;const opening=String(rawOpening||'').replace(/[\[\]【】|｜]/g,'').replace(/\s+/g,' ').trim().slice(0,42),thoughts=thoughtEggWords(rawThoughts),ending=String(rawEnding||'').replace(/[\[\]【】|｜]/g,'').replace(/\s+/g,' ').trim().slice(0,38);if(!opening||thoughts.length<12||!ending||!thoughtEggNovel(c,opening,thoughts,ending))return null;const time=Date.now(),id=uid(),payload=typeof NorthThoughtCardEffects!=='undefined'&&NorthThoughtCardEffects.createPayload?NorthThoughtCardEffects.createPayload({opening,thoughts,ending,sender:c.remark||c.name,seed:id,time}):{opening,thoughts,ending,seed:id,time};c.thoughtEggLastAt=time;c.thoughtEggHistory=thoughtEggHistory(c).concat([{at:time,words:[opening].concat(thoughts,ending)}]).slice(-6);return {role:'assistant',type:'thoughtcard',from:'ta',opening:payload.opening||opening,thoughts:payload.thoughts||thoughts,ending:payload.ending||ending,seed:payload.seed||id,id,time};}
