function foodReceiptReplyMatches(info,content){if(!info)return false;const x=String(content||'').replace(/[\s\n]+/g,' ').trim();if(!x)return false;const acknowledged=/(?:送到|到了|到啦|收到|签收|趁热|先吃|快吃|吃吧|吃完|尝尝|味道|好不好吃|别饿|填肚子|凉了)/.test(x);if(!acknowledged)return false;const name=String(info.name||'').trim();return !name||x.includes(name)||/(?:外卖|饭|粥|餐|吃|味道)/.test(x);}
