function calPrefs(){return (S.calendarPreferences||{})[actId()]||{};}
function calEventOwned(e){return !!e&&(!e.owner||e.owner===actId())&&(!e.calendarId||!!calCollection(e.calendarId));}
function calEventVisible(e){if(!calEventOwned(e))return false;const c=e.calendarId&&calCollection(e.calendarId),p=calPrefs();return (!c||c.visible!==false)&&(!e.declined||p.showDeclined===true)&&(!(e.type==='reminder'&&e.completed)||p.showCompleted!==false)&&(e.calendarId||e.editorVersion===1||p.legacyVisible!==false);}
function calRoleEvents(cid){return (S.calendar||[]).filter(e=>{if(!calEventOwned(e))return false;if(e.invitedBy)return e.invitedBy===cid;if(e.createdBy===cid)return true;if((e.invitees||[]).includes(cid))return true;if(e.editorVersion===1&&!e._legacyCalendarRecord&&!e.calendarId)return e.contactId===cid;if(!e.calendarId)return true;const c=calCollection(e.calendarId);return !!c&&(c.sharedWith||[]).includes(cid);});}
function calRoleSharedText(cid){return calCollections().filter(c=>(c.sharedWith||[]).includes(cid)).map(c=>'日历「'+c.name+'」：'+((S.calendar||[]).filter(e=>e.calendarId===c.id).map(calEventFact).join('；')||'尚无日程')).join('\n');}
function calEventAlerts(e){const c=e.calendarId&&calCollection(e.calendarId);return calEventOwned(e)&&(!c||c.alerts!==false)&&(!e.calendarId||c&&(c.sharedWith||[]).includes(e.contactId));}
function calPanelOpen(){calEnsure();_calPanelOwner=actId();_calPanel='list';_calDraft=null;render();}
function calPanelClose(){if(_calSaving)return;_calPanel='';_calDraft=null;render();}
function calPanelBack(){if(_calSaving)return;if(_calPanel==='customColor')_calPanel='colors';else if(_calPanel==='roles'||_calPanel==='colors')_calPanel='edit';else{_calPanel='list';_calDraft=null;}render();}
function calCollectionEdit(id){if(_calSaving)return;const c=id&&calCollection(id);if(id&&!c)return;_calPanelOwner=actId();_calDraft=c?JSON.parse(JSON.stringify(c)):{id:uid(),owner:actId(),name:'',color:'#009aff',visible:true,alerts:true,sharedWith:[]};_calPanel='edit';render();}
function calDraftName(v){if(_calDraft&&_calPanelOwner===actId())_calDraft.name=String(v).slice(0,60);}
function calDraftToggle(){if(_calDraft&&!_calSaving){_calDraft.alerts=!_calDraft.alerts;render();}}
function calColorValue(value){const v=String(value||'').trim();return /^#?[0-9a-f]{6}$/i.test(v)?'#'+v.replace(/^#/,'').toLowerCase():'';}
async function calDraftColor(color){const value=calColorValue(color);if(!_calDraft||_calSaving||!value||_calPanelOwner!==actId())return;const draft=_calDraft,oldDraft=draft.color,c=calCollection(draft.id),state=S,owner=actId(),old=c&&c.color;draft.color=value;if(!c){render();return;}c.color=value;_calSaving=true;render();const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){c.color=old;if(_calDraft===draft)draft.color=oldDraft;toast('颜色保存失败，请重试');}render();}
function calColorName(color){const value=calColorValue(color),preset=CAL_COLORS.find(x=>x[1]===value);return preset?preset[0]:'自定义颜色';}
let _calCustomHex='#009aff',_calPickerTab='grid',_calSpectrumHsv=null;
function calRgb(color){const value=calColorValue(color)||'#009aff';return [1,3,5].map(i=>parseInt(value.slice(i,i+2),16));}
function calRgbHex(r,g,b){return '#'+[r,g,b].map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('');}
function calHsvHex(h,s,v){const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c,parts=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return calRgbHex(...parts.map(n=>(n+m)*255));}
function calHexHsv(color){const rgb=calRgb(color).map(x=>x/255),max=Math.max(...rgb),min=Math.min(...rgb),d=max-min;let h=d===0?0:max===rgb[0]?60*((rgb[1]-rgb[2])/d%6):max===rgb[1]?60*((rgb[2]-rgb[0])/d+2):60*((rgb[0]-rgb[1])/d+4);return {h:(h+360)%360,s:max?d/max:0,v:max};}
function calCustomOpen(){if(!_calDraft||_calSaving||_calPanelOwner!==actId())return;_calCustomHex=calColorValue(_calDraft.color)||'#009aff';_calPickerTab='grid';_calSpectrumHsv=calHexHsv(_calCustomHex);_calPanel='customColor';render();}
function calCustomInput(value){if(_calSaving||_calPanelOwner!==actId())return;const color=calColorValue(value);if(!color)return;_calCustomHex=color;_calSpectrumHsv=calHexHsv(color);calPickerSync();}
function calRgbTrack(rgb,index){const from=rgb.slice(),to=rgb.slice();from[index]=0;to[index]=255;return 'linear-gradient(to right,'+calRgbHex(...from)+','+calRgbHex(...to)+')';}
function calPickerSync(){const color=calColorValue(_calCustomHex)||'#009aff',rgb=calRgb(color),hsv=_calPickerTab==='spectrum'&&_calSpectrumHsv?_calSpectrumHsv:calHexHsv(color),swatch=$('#cal_custom_preview'),hex=$('#cal_custom_hex'),spectrum=$('#cal_color_spectrum'),point=$('#cal_spectrum_point');if(swatch)swatch.style.background=color;if(hex&&document.activeElement!==hex)hex.value=color.toUpperCase();['r','g','b'].forEach((k,i)=>{const slider=$('#cal_rgb_'+k),number=$('#cal_rgb_value_'+k);if(slider){slider.value=rgb[i];slider.style.background=calRgbTrack(rgb,i);}if(number)number.textContent=rgb[i];});const brightness=$('#cal_spectrum_value');if(brightness){brightness.value=Math.round(hsv.v*100);brightness.style.background='linear-gradient(to right,#000,'+calHsvHex(hsv.h,hsv.s,1)+')';}if(spectrum)spectrum.style.setProperty('--cal-spectrum-v',String(hsv.v));if(point){point.style.left=hsv.h/360*100+'%';point.style.top=(1-hsv.s)*100+'%';point.style.background=color;}document.querySelectorAll('[data-cal-swatch]').forEach(b=>{const selected=b.dataset.calSwatch===color;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});}
function calPickerTab(tab){if(_calSaving||_calPanelOwner!==actId()||!['grid','spectrum','sliders'].includes(tab))return;_calPickerTab=tab;render();}
function calCustomPick(color){calCustomInput(color);}
function calRgbSlide(){const rgb=['r','g','b'].map(k=>+(($('#cal_rgb_'+k)||{}).value||0));calCustomInput(calRgbHex(...rgb));}
function calSpectrumPoint(event){if(_calSaving||_calPanelOwner!==actId()||_calPanel!=='customColor')return;const box=event.currentTarget;if(event.type==='pointerdown'){if(event.button!==0||event.isPrimary===false)return;box.setPointerCapture(event.pointerId);}else if(!box.hasPointerCapture(event.pointerId))return;const rect=box.getBoundingClientRect(),h=Math.max(0,Math.min(.99999,(event.clientX-rect.left)/rect.width))*360,s=1-Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height)),v=(_calSpectrumHsv||calHexHsv(_calCustomHex)).v;_calSpectrumHsv={h,s,v};_calCustomHex=calHsvHex(h,s,v);calPickerSync();}
function calSpectrumValue(value){if(_calSaving||_calPanelOwner!==actId())return;const hsv=_calSpectrumHsv||calHexHsv(_calCustomHex);_calSpectrumHsv={...hsv,v:Math.max(0,Math.min(100,+value))/100};_calCustomHex=calHsvHex(_calSpectrumHsv.h,_calSpectrumHsv.s,_calSpectrumHsv.v);calPickerSync();}
function calColorSwatches(){return ((S.calendarColorSwatches||{})[actId()]||[]).map(calColorValue).filter(Boolean).slice(-12);}
async function calColorFavorite(){if(_calSaving||_calPanelOwner!==actId())return;const color=calColorValue(_calCustomHex);if(!color||calColorSwatches().includes(color)){toast('这个颜色已收藏');return;}const state=S,owner=actId(),prior=S.calendarColorSwatches;_calSaving=true;S.calendarColorSwatches={...(prior||{}),[owner]:calColorSwatches().concat(color).slice(-12)};const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){S.calendarColorSwatches=prior;toast('颜色收藏保存失败');return;}render();}
async function calCustomApply(){const color=calColorValue(($('#cal_custom_hex')||{}).value);if(!color){toast('请输入6位颜色值，例如 #7C6CF2');return;}if(!_calDraft||_calSaving||_calPanelOwner!==actId())return;_calPanel='colors';await calDraftColor(color);}
function calColorHeader(title){return '<header class="cal-sheet-header"><button class="photo-album-glass cal-sheet-close" aria-label="返回日历设置" onclick="calPanelBack()">'+calIcon('back')+'</button><strong>'+title+'</strong><span></span></header>';}
function calColorsPage(){const value=calColorValue(_calDraft.color)||'#009aff',custom=!CAL_COLORS.some(c=>c[1]===value);return calColorHeader('日历颜色')+'<main class="cal-sheet-body cal-colors-body"><h3>颜色</h3><section class="cal-sheet-group">'+CAL_COLORS.map(c=>'<button class="cal-sheet-row" onclick="'+calCall('calDraftColor',c[1])+'"><i class="cal-color-dot" style="background:'+c[1]+'"></i><span>'+c[0]+'</span><em class="cal-color-selected">'+(value===c[1]?calIcon('check'):'')+'</em></button>').join('')+'<button class="cal-sheet-row" onclick="calCustomOpen()"><i class="cal-color-dot" style="background:'+value+'"></i><span>自定义…</span><em class="cal-color-selected">'+(custom?calIcon('check'):'')+'</em></button></section></main>';}
function calPickerGrid(){const hues=[190,220,260,290,330,5,25,40,48,60,75,100],cells=[];for(let row=0;row<10;row++)for(let col=0;col<12;col++){const value=row===0?calRgbHex(...Array(3).fill(255*(1-col/11))):calHsvHex(hues[col],row<6?1:1-(row-5)*.21,row<6?.22+(row-1)*.195:1);cells.push('<button data-cal-swatch="'+value+'" aria-label="选择 '+value.toUpperCase()+'" aria-pressed="'+(value===_calCustomHex)+'" class="cal-grid-swatch'+(value===_calCustomHex?' selected':'')+'" style="background:'+value+'" onclick="'+calCall('calCustomPick',value)+'"></button>');}return '<div class="cal-color-grid">'+cells.join('')+'</div>';}
function calPickerSpectrum(){const hsv=_calSpectrumHsv||calHexHsv(_calCustomHex);return '<div id="cal_color_spectrum" class="cal-color-spectrum" style="--cal-spectrum-v:'+hsv.v+'" onpointerdown="calSpectrumPoint(event)" onpointermove="calSpectrumPoint(event)" aria-label="拖动光谱选色"><i id="cal_spectrum_point" style="left:'+hsv.h/360*100+'%;top:'+(1-hsv.s)*100+'%;background:'+_calCustomHex+'"></i></div><label class="cal-spectrum-label" for="cal_spectrum_value">亮度</label><input id="cal_spectrum_value" style="background:linear-gradient(to right,#000,'+calHsvHex(hsv.h,hsv.s,1)+')" type="range" min="0" max="100" value="'+Math.round(hsv.v*100)+'" aria-label="光谱亮度" oninput="calSpectrumValue(this.value)">';}
function calPickerSliders(){const rgb=calRgb(_calCustomHex);return '<div class="cal-rgb-sliders">'+[['r','红色'],['g','绿色'],['b','蓝色']].map((k,i)=>'<label for="cal_rgb_'+k[0]+'"><span>'+k[1]+'</span><b id="cal_rgb_value_'+k[0]+'">'+rgb[i]+'</b></label><input id="cal_rgb_'+k[0]+'" class="cal-range-'+k[0]+'" style="background:'+calRgbTrack(rgb,i)+'" type="range" min="0" max="255" step="1" value="'+rgb[i]+'" aria-label="'+k[1]+'通道" oninput="calRgbSlide()">').join('')+'</div>';}
function calCustomColorPage(){const value=calColorValue(_calCustomHex)||'#009aff',saved=calColorSwatches();return '<header class="cal-sheet-header"><span></span><strong>颜色</strong><button class="photo-album-glass cal-sheet-close" aria-label="关闭调色板" onclick="calPanelBack()">'+calIcon('close')+'</button></header><main class="cal-sheet-body cal-picker-body"><div class="cal-picker-tabs" role="tablist">'+[['grid','网格'],['spectrum','光谱'],['sliders','滑块']].map(t=>'<button role="tab" aria-selected="'+(_calPickerTab===t[0])+'" class="'+(_calPickerTab===t[0]?'selected':'')+'" onclick="'+calCall('calPickerTab',t[0])+'">'+t[1]+'</button>').join('')+'</div><section class="cal-picker-surface">'+(_calPickerTab==='grid'?calPickerGrid():_calPickerTab==='spectrum'?calPickerSpectrum():calPickerSliders())+'</section><div class="cal-picker-bottom"><div id="cal_custom_preview" class="cal-custom-preview" style="background:'+value+'"></div><div class="cal-picker-saved">'+saved.map(color=>'<button class="cal-saved-swatch" data-cal-swatch="'+color+'" aria-label="收藏颜色 '+color.toUpperCase()+'" style="background:'+color+'" onclick="'+calCall('calCustomPick',color)+'"></button>').join('')+'<button class="cal-save-swatch" aria-label="收藏当前颜色" onclick="calColorFavorite()">'+calIcon('plus')+'</button></div></div><div class="cal-picker-hex"><label for="cal_custom_hex">颜色值</label><input id="cal_custom_hex" maxlength="7" aria-label="自定义颜色值" value="'+value.toUpperCase()+'" oninput="calCustomInput(this.value)" spellcheck="false" autocomplete="off"></div><button class="cal-sheet-group cal-sheet-row cal-custom-apply" onclick="calCustomApply()">使用这个颜色</button></main>';}

function calDraftRole(id){if(!_calDraft||_calSaving||_calPanelOwner!==actId())return;const c=getC(id);if(!c||c.deleted||c.blocked)return;const a=_calDraft.sharedWith||[];_calDraft.sharedWith=a.includes(id)?a.filter(x=>x!==id):a.concat(id);render();}
async function calPersist(){if(NORTH_PREVIEW)return true;try{return !!(await saveNowAsync());}catch(_){return false;}}
async function calPreference(key){if(_calSaving||_calPanelOwner!==actId()||!['legacyVisible','showCompleted','showDeclined','periodVisible','periodReminders'].includes(key))return;_calSaving=true;const state=S,owner=actId(),old=S.calendarPreferences;S.calendarPreferences={...(old||{}),[owner]:{...calPrefs(),[key]:key==='showDeclined'?calPrefs()[key]!==true:calPrefs()[key]===false}};const ok=await calPersist();if(S===state&&actId()===owner){if(!ok)S.calendarPreferences=old;render();}_calSaving=false;}
async function calCollectionVisible(id){if(_calSaving||_calPanelOwner!==actId())return;const c=calCollection(id);if(!c)return;_calSaving=true;const state=S,owner=actId(),old=c.visible;c.visible=c.visible===false;const ok=await calPersist();if(S===state&&actId()===owner){if(!ok)c.visible=old;render();}_calSaving=false;}
function calRollbackCards(cards,cid,owner,prior){const key=accountMessageKey(cid,owner),ids=new Set(cards.map(m=>m.id)),remaining=(S.messages[key]||[]).filter(m=>!ids.has(m.id));if(!remaining.length&&!(key in prior))delete S.messages[key];else S.messages[key]=remaining;}
async function calCollectionSave(){if(_calSaving||!_calDraft||_calPanelOwner!==actId())return;const d=JSON.parse(JSON.stringify(_calDraft));d.name=d.name.trim();if(!d.name){toast('请填写日历名称');return;}d.sharedWith=(d.sharedWith||[]).filter(id=>{const c=getC(id);return c&&!c.deleted&&!c.blocked;});const old=calCollection(d.id),added=d.sharedWith.filter(id=>!old||!(old.sharedWith||[]).includes(id)),state=S,owner=actId(),prior=S.calendarCollections,priorMessages=S.messages,createdCards=[];_calSaving=true;S.calendarCollections=(prior||[]).filter(x=>x.id!==d.id).concat(d);S.messages={...S.messages};added.forEach(id=>{const existing=msgs(id);S.messages[accountMessageKey(id,owner)]=existing.slice();const card={id:uid(),role:'user',type:'calendarshare',calendarId:d.id,calendarOwner:owner,calendarRecipient:id,time:Date.now()};createdCards.push(card);msgs(id).push(card);});const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){S.calendarCollections=prior;added.forEach(id=>calRollbackCards(createdCards,id,owner,priorMessages));toast('保存失败，请重试');return;}_calPanel='list';_calDraft=null;render();toast('日历已保存'+(added.length?'，共享卡片已发送':''));}
function calShareAllowed(m){return !!m&&m.calendarOwner===actId()&&!!calCollection(m.calendarId)&&(calCollection(m.calendarId).sharedWith||[]).includes(m.calendarRecipient);}
function calShareText(m){if(!calShareAllowed(m))return '[日历共享已不可用]';const c=calCollection(m.calendarId);return '[共享日历] '+c.name+'；'+((S.calendar||[]).filter(e=>e.calendarId===c.id).map(calEventFact).join('；')||'暂无日程')+'。仅获授权角色可读取，无编辑权限。';}
function calShareCard(m){const allowed=calShareAllowed(m),c=allowed&&calCollection(m.calendarId),color=c?(calColorValue(c.color)||'#009aff'):'#8e8e93',count=c?(S.calendar||[]).filter(e=>e.calendarId===c.id).length:0;return '<button class="cal-share-card cal-share-rich" style="--cal-card-accent:'+color+'" onclick="'+calAttr('event.stopPropagation();')+calCall('calShareOpen',m.calendarId,m.calendarOwner,m.calendarRecipient)+'"><span class="cal-card-head"><span class="cal-card-icon">'+calIcon('calendar')+'</span><span class="cal-card-kind">共享日历</span></span><strong>'+esc(c?c.name:'日历共享已不可用')+'</strong><span class="cal-card-meta">'+esc(c?(S.me.name||'用户')+' 分享给 '+calRoleName(m.calendarRecipient):'权限已撤销或账户不同')+'</span><span class="cal-card-footer"><span>'+ (c?count+' 项日程':'分享不可用')+'</span><span>'+(c?'查看日历 '+calIcon('chevron'):'')+'</span></span></button>';}

function calShareOpen(id,owner,cid){if(owner!==actId()||!calShareAllowed({calendarId:id,calendarOwner:owner,calendarRecipient:cid})||cur().p!=='chat'||cur().id!==cid){toast('这份共享日历不可用');return;}go('calendarShared',{kind:'user',calendarId:id,owner,cid});}
function calSwitch(on,action,label,disabled){return '<button role="switch" aria-label="'+calAttr(label)+'" aria-checked="'+!!on+'" class="cal-switch'+(on?' on':'')+'" '+(disabled?'disabled':'onclick="'+calAttr(action)+'"')+'><i></i></button>';}
function calPanelHeader(title,back,confirm){return '<header class="cal-sheet-header"><button aria-label="'+(back?'返回日历':'关闭日历管理')+'" class="photo-album-glass cal-sheet-close" onclick="'+(back?'calPanelBack()':'calPanelClose()')+'">'+calIcon('close')+'</button><strong>'+title+'</strong>'+(confirm?'<button aria-label="保存日历" class="photo-album-glass cal-sheet-close cal-sheet-confirm" onclick="calCollectionSave()" '+(_calSaving?'disabled':'')+'>'+calIcon('check')+'</button>':'<span></span>')+'</header>';}
function renderCalPanel(){if(_calPanelOwner!==actId()){_calPanel='';_calDraft=null;return renderCalendar();}if(_calPanel==='periods'||_calPanel==='periodEdit')return renderCalPeriod();if(_calPanel==='locate')return renderCalJump();if(_calPanel==='newEvent')return renderCalNewEvent();if(_calPanel==='eventInvite'||_calPanel==='eventInvitePick')return renderCalInvite();const name=S.me.name||'用户',p=calPrefs();let body='';if(_calPanel==='list'){const list=calCollections();body=calPanelHeader('日历',false,false)+'<main class="cal-sheet-body"><h3>'+esc(name)+'</h3>'+(list.length?'<section class="cal-sheet-group">'+list.map(c=>'<div class="cal-sheet-row"><button class="cal-check" aria-label="'+calAttr(c.name)+'显示开关" aria-pressed="'+(c.visible!==false)+'" style="--cal-color:'+(/^#[0-9a-f]{6}$/i.test(c.color||'')?c.color:'#009aff')+'" onclick="'+calCall('calCollectionVisible',c.id)+'">'+(c.visible===false?'':calIcon('check'))+'</button><span>'+esc(c.name)+((c.sharedWith||[]).length?'<small>已共享给 '+c.sharedWith.map(id=>esc(calRoleName(id))).join('、')+'</small>':'')+'</span><button class="cal-info" aria-label="编辑'+calAttr(c.name)+'" onclick="'+calCall('calCollectionEdit',c.id)+'">'+calIcon('info')+'</button></div>').join('')+'</section>':'<div class="cal-sheet-empty">尚未添加日历</div>')+'<h3>其他</h3><section class="cal-sheet-group">'+((S.calendar||[]).some(e=>!e.calendarId)?'<div class="cal-sheet-row"><button class="cal-check" style="--cal-color:#009aff" aria-label="已有日程显示开关" onclick="calPreference(\'legacyVisible\')">'+(p.legacyVisible===false?'':calIcon('check'))+'</button><span>已有日程<small>保留原有日程与婚礼记录</small></span></div>':'')+'<button class="cal-sheet-row" onclick="calLegacyRecordsOpen()"><span>经期记录</span><em class="cal-row-chevron">'+calIcon('chevron')+'</em></button><button class="cal-sheet-row" onclick="calLocate()"><span>跳转到日期</span><em class="cal-row-chevron">'+calIcon('chevron')+'</em></button></section><section class="cal-sheet-group cal-sheet-options"><div class="cal-sheet-row"><span>显示已拒绝的日程<small>只影响你拒绝的角色邀请</small></span>'+calSwitch(p.showDeclined===true,"calPreference('showDeclined')",'显示已拒绝的日程')+'</div><div class="cal-sheet-row"><span>显示完成的提醒事项</span>'+calSwitch(p.showCompleted!==false,"calPreference('showCompleted')",'显示完成的提醒事项')+'</div></section><button class="cal-sheet-group cal-sheet-row cal-add-calendar" onclick="calCollectionEdit()">'+calIcon('calendar')+'<span>添加日历</span></button></main>';}
else if(_calPanel==='edit'){const d=_calDraft,color=[calColorName(d.color),calColorValue(d.color)||'#009aff'];body=calPanelHeader(calCollection(d.id)?'编辑日历':'添加日历',true,true)+'<main class="cal-sheet-body cal-create-body"><section class="cal-sheet-group"><input id="cal_collection_name" maxlength="60" placeholder="日历名称" aria-label="日历名称" value="'+calAttr(d.name)+'" oninput="calDraftName(this.value)"></section><section class="cal-sheet-group cal-sheet-row"><span>账户</span><em>'+esc(name)+'</em></section><h3>共享给</h3><section class="cal-sheet-group"><button class="cal-sheet-row cal-red" onclick="_calPanel=\'roles\';render()">'+calIcon('person')+'<span>添加联系人</span><em class="cal-row-chevron">'+calIcon('chevron')+'</em></button>'+(d.sharedWith||[]).map(id=>'<div class="cal-sheet-row"><span>'+esc(calRoleName(id))+'</span><button class="cal-red cal-remove-person" onclick="'+calCall('calDraftRole',id)+'">移除</button></div>').join('')+'</section><h3>颜色</h3><button class="cal-sheet-group cal-sheet-row" onclick="_calPanel=\'colors\';render()"><i class="cal-color-dot" style="background:'+color[1]+'"></i><span>'+color[0]+'</span><em class="cal-row-chevron">'+calIcon('chevron')+'</em></button><h3>通知</h3><section class="cal-sheet-group cal-sheet-row"><span>日程提醒</span>'+calSwitch(d.alerts,'calDraftToggle()','日程提醒')+'</section><p class="cal-sheet-note">允许该日历中的日程由指定角色提醒。小手机运行时执行；关闭应用后的系统通知开发中。</p></main>';}
else if(_calPanel==='colors')body=calColorsPage();else if(_calPanel==='customColor')body=calCustomColorPage();
else {body=calPanelHeader(_calPanel==='roles'?'添加联系人':'颜色',true,false)+'<main class="cal-sheet-body"><section class="cal-sheet-group">'+(_calPanel==='roles'?(S.contacts||[]).filter(c=>!c.deleted&&!c.blocked).map(c=>'<button class="cal-sheet-row" onclick="'+calCall('calDraftRole',c.id)+'"><span>'+esc(c.remark||c.name)+'</span><em>'+(_calDraft.sharedWith.includes(c.id)?calIcon('check'):'')+'</em></button>').join('')||'<div class="cal-sheet-row">暂无可共享的角色</div>':CAL_COLORS.map(c=>'<button class="cal-sheet-row" onclick="'+calCall('calDraftColor',c[1])+'"><i class="cal-color-dot" style="background:'+c[1]+'"></i><span>'+c[0]+'</span><em>'+(_calDraft.color===c[1]?calIcon('check'):'')+'</em></button>').join(''))+'</section><button class="cal-sheet-group cal-sheet-row" onclick="_calPanel=\'edit\';render()">完成</button></main>';}
return '<div class="cal-sheet-page'+(_calPanel==='customColor'?' cal-custom-color-page':'')+'">'+body+'</div>';}
function calEventOpen(id,date){const p=periodRecords().find(p=>id===p.id||String(id).startsWith('period-day-'+p.id+'-'));if(p){calPeriodOpen(p.id);return;}calDetailOpen(id,date);}

async function calReminderToggle(id,date){if(_calSaving)return;const e=(S.calendar||[]).find(x=>x.id===id&&x.type==='reminder'&&calEventOwned(x));if(!e)return;const series=e.repeat&&e.repeat.unit!=='none';if(series&&(!roleCalDateValid(date)||!calOccurrenceStarts(e,date,date).length))return;_calSaving=true;const state=S,owner=actId(),old=e.completed,oldDates=e.completedDates;if(series)e.completedDates=(e.completedDates||[]).includes(date)?e.completedDates.filter(x=>x!==date):(e.completedDates||[]).concat(date);else e.completed=!e.completed;const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){e.completed=old;e.completedDates=oldDates;toast('保存失败');return;}closeModal();render();}

/* Character calendars are separate from user calendars; only an explicit model share creates a card. */
function roleCalRows(cid){return (S.roleCalendar||[]).filter(e=>e&&e.owner===actId()&&e.cid===cid);}


function calParticipation(e,cid){const p=e&&e.roleParticipation&&e.roleParticipation[cid];return {mode:p&&['inform','join','remind'].includes(p.mode)?p.mode:'remind',prepare:!!(p&&p.prepare),followup:!!(p&&p.followup),response:p&&p.response||'pending'};}
function calParticipationLabel(e,cid){const p=calParticipation(e,cid);return ({inform:'只告知',join:'一起参与',remind:'帮我提醒'})[p.mode]+' · '+({pending:'等待回应',accepted:'愿意参与',tentative:'待定',declined:'暂不参与'})[p.response]+(p.prepare?' · 提前准备':'')+(p.followup?' · 结束后关心':'');}
function calRoleCanRemind(e,cid){const p=calParticipation(e,cid);return p.mode==='remind'&&p.response!=='declined'&&p.response!=='tentative';}
function calParticipationHTML(e,draft){const ids=e.invitees||[];if(!ids.length)return '';return '<section class="cal-sheet-group cal-participation">'+ids.map(cid=>{const p=calParticipation(e,cid);return '<div class="cal-participant"><div class="cal-participant-head">'+av(getC(cid)&&getC(cid).avatar,'cal-invite-avatar')+'<strong>'+esc(calRoleName(cid))+'</strong><small>'+esc(({pending:'等待回应',accepted:'愿意参与',tentative:'待定',declined:'暂不参与'})[p.response])+'</small></div><div class="cal-picker-tabs">'+[['inform','只告知'],['join','一起参与'],['remind','帮我提醒']].map(([mode,label])=>'<button aria-label="'+esc(calRoleName(cid)+' '+label)+'" aria-pressed="'+(mode===p.mode)+'" class="'+(mode===p.mode?'selected':'')+'" onclick="'+calCall('calParticipationSet',e.id,cid,'mode',mode,draft?'draft':'saved')+'">'+label+'</button>').join('')+'</div>'+(p.mode!=='inform'?'<div class="cal-sheet-row"><span>提前准备<small>提醒之前，单独关心一次</small></span>'+calSwitch(p.prepare,'calParticipationSet('+[e.id,cid,'prepare',!p.prepare,draft?'draft':'saved'].map(x=>JSON.stringify(x)).join(',')+')',calRoleName(cid)+' 提前准备')+'</div><div class="cal-sheet-row"><span>结束后关心<small>有结束时间时，当天只询问一次</small></span>'+calSwitch(p.followup,'calParticipationSet('+[e.id,cid,'followup',!p.followup,draft?'draft':'saved'].map(x=>JSON.stringify(x)).join(',')+')',calRoleName(cid)+' 结束后关心')+'</div>':'')+'</div>';}).join('')+'</section><p class="cal-new-note">只告知会停止这条日程的角色提醒与关心，不会关闭你自己的日程提醒；一起参与由角色回应。准备和关心单独开启，时间结束不会自动标记完成。实际发言仍受角色主动消息与在线设置限制。</p>';}
async function calParticipationSet(id,cid,key,value,scope){if(_calSaving||!['mode','prepare','followup'].includes(key))return;const e=scope==='draft'?_calEventDraft:(S.calendar||[]).find(e=>e.id===id&&calEventOwned(e));if(!e||(scope==='draft'&&_calPanelOwner!==actId())||!(e.invitees||[]).includes(cid)||!calInviteRoles().some(c=>c.id===cid)||key==='mode'&&!['inform','join','remind'].includes(value))return;const prev=JSON.parse(JSON.stringify(e)),p=calParticipation(e,cid);p[key]=key==='mode'?value:!!value;if(key==='mode'&&p.mode==='inform'){p.prepare=false;p.followup=false;}e.roleParticipation={...(e.roleParticipation||{}),[cid]:p};if(scope==='draft'){calNewRender();return;}const state=S,owner=actId(),scrollNode=$('.cal-detail-scroll'),scroll=scrollNode?scrollNode.scrollTop:0;e.revision=(+e.revision||0)+1;e.alertRevision=(+e.alertRevision||0)+1;_calSaving=true;const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){Object.keys(e).forEach(k=>delete e[k]);Object.assign(e,prev);toast('参与设置保存失败');}render();const body=$('.cal-detail-scroll');if(body)body.scrollTop=scroll;}
function calCareWindow(e,date,stage){const start=calEventLocalAt(e,date),end=e.endTime||e.allDay?calEventLocalAt({...e,endDate:calAddDays(date,calDayDiff(e.endDate||e.date,e.date))},date,true):NaN;return stage==='prepare'?{from:start-Math.max(60,(e.alertMinutes>=0?e.alertMinutes:0)+60)*60000,to:start-Math.max(30,(e.alertMinutes>=0?e.alertMinutes:0)+15)*60000}:stage==='followup'&&Number.isFinite(end)?{from:end+1800000,to:Math.min(end+21600000,new Date(calDateString(new Date(end))+'T23:59:59').getTime())}:null;}
function calCareValid(meta,cid,owner){const e=(S.calendar||[]).find(x=>x.id===meta.eventId),c=e&&e.calendarId&&calCollection(e.calendarId),p=calParticipation(e,cid),w=e&&calCareWindow(e,meta.date,meta.stage),now=Date.now();return !!(e&&w&&meta.owner===owner&&owner===actId()&&meta.roleId===cid&&(+meta.revision||0)===(+e.revision||0)&&calInvitedEvent(e,cid)&&p.mode!=='inform'&&p.response!=='declined'&&p.response!=='tentative'&&p[meta.stage]&&(!c||c.alerts!==false)&&!e.completed&&!(e.completedDates||[]).includes(meta.date)&&calOccurrenceStarts(e,meta.date,meta.date).length&&now>=w.from&&now<=w.to);}
function calCareNote(e,cid,date,stage){const meta={owner:actId(),eventId:e.id,roleId:cid,date,stage,revision:+e.revision||0};return featureEventNote(stage==='prepare'?'日程准备关心':'日程结束关心','玩家单独开启了这条日程的'+(stage==='prepare'?'提前准备':'结束后关心')+'。真实记录：'+calEventFact({...e,date})+'。参与方式：'+calParticipationLabel(e,cid)+'。'+(stage==='prepare'?'可以自然问准备情况或按记录给具体建议，不编造材料要求。':'时间已经结束，但玩家尚未确认完成。可以自然询问结果，不宣称已经完成，不自动延期或标记。')+'按你的性格和关系说话，不套固定话术；不重复催促，不读取其他未共享日程。')+'\n[日程受邀提醒作用域|'+encodeURIComponent(JSON.stringify(meta))+']';}
function calFireCalendarCare(now){now=Number.isFinite(+now)?+now:Date.now();const state=S,owner=actId(),day=calDateString(new Date(now));(S.calendar||[]).filter(e=>e.editorVersion===1&&calEventOwned(e)&&!e.completed).forEach(e=>calOccurrenceStarts(e,calAddDays(day,-8),calAddDays(day,1)).forEach(date=>(e.invitees||[]).forEach(cid=>['prepare','followup'].forEach(stage=>{const meta={owner,eventId:e.id,roleId:cid,date,stage,revision:+e.revision||0},key=owner+'|'+e.id+'|'+date+'|'+cid+'|'+stage;if(!calCareValid(meta,cid,owner)||S.calendarRoleFired&&S.calendarRoleFired[key]||_calInvitedBusy[key]&&now-_calInvitedBusy[key]<180000||roleOnlineProactiveBlocked(cid))return;const note=calCareNote(e,cid,date,stage);_calInvitedBusy[key]=now;let settled=false;const done=async ok=>{if(settled)return;settled=true;delete _calInvitedBusy[key];if(!ok||S!==state||actId()!==owner||!calCareValid(meta,cid,owner))return;S.calendarRoleFired=S.calendarRoleFired||{};S.calendarRoleFired[key]=Date.now();await calPersist();};if(!scheduleFeatureReply(cid,note,0,done,owner))done(false);})))) ;}
async function calRoleParticipationConsume(content,c){const text=String(content||''),re=/[\[【]回应日程邀请[|｜]([^|｜\]】]+)[|｜](accepted|tentative|declined)[\]】]/g,matches=[...text.matchAll(re)];if(!matches.length)return {text,changed:false};if(!c||getC(c.id)!==c||c.deleted||c.blocked)return {text:text.replace(re,'').trim(),changed:false};const state=S,owner=actId(),changes=[];for(const m of matches){const e=(S.calendar||[]).find(e=>e.id===m[1]&&calInvitedEvent(e,c.id));if(!e||changes.some(x=>x.e===e))continue;changes.push({e,prev:e.roleParticipation,revision:e.revision});const p=calParticipation(e,c.id);p.response=m[2];e.roleParticipation={...(e.roleParticipation||{}),[c.id]:p};e.revision=(+e.revision||0)+1;}if(!changes.length)return {text:text.replace(re,'').trim(),changed:false};const ok=await calPersist();if(S!==state||actId()!==owner)return {text:'',changed:false};if(!ok){changes.forEach(x=>{x.e.roleParticipation=x.prev;x.e.revision=x.revision;});return {text:'',changed:false};}return {text:text.replace(re,'').trim(),changed:true};}
async function calEventOutcome(id,date){if(_calSaving)return;const e=(S.calendar||[]).find(e=>e.id===id&&calEventOwned(e)&&e.type==='event'&&!e.invitedBy);if(!e||!calOccurrenceStarts(e,date,date).length)return;const prev=(e.completedDates||[]).slice(),state=S,owner=actId();e.completedDates=prev.includes(date)?prev.filter(x=>x!==date):prev.concat(date);_calSaving=true;const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){e.completedDates=prev;toast('完成状态保存失败');}render();}

function calPlayerPrompt(c){return '\n\n# 帮玩家安排日程\n玩家可以口头或打字请你在日历安排事情。按你自己的性格、语气和关系自然交流，不套固定提问模板。日期、开始时间（或玩家明确说全天）和事项名称缺哪项就先问清；相对日期结合当前日期换算，模糊的“晚点”“改天”不要猜。玩家已说过的信息不要重复问。可自然讨论结束时间、重复频率、提前提醒、地点、备注和日历分类；没有说的选项保持空或无，不编造时长、日程或承诺已登记。只有玩家明确要求你安排且关键信息完整时，用单独一行 [为你安排日程|'+JSON.stringify({date:'YYYY-MM-DD',time:'HH:MM',title:'玩家确定的事项',endDate:'',endTime:'',repeat:'none',alertMinutes:-1,calendarId:'',location:'',notes:''})+']；全天使用allDay:true并留空time。repeat可用none/day/week/biweekly/month/year，提醒-1表示无，其他值为提前分钟。结束未确定时留空。不会操作时可按日历右上＋、填写标题和日期时间、右上勾保存这些真实入口解释，也可以直接帮ta做好。不要自行开启提前准备或结束关心，这些由玩家在日程详情选择。只新建玩家明确要的日程，不靠标签改已有记录，不将婚礼特殊流程混入。保存成功会自动把安排好的真实日程分享给玩家，发出可点击卡片，无需另外分享自己的日历。结束后不能自动认定完成，也不能自行修改已有日程；可先提出调整建议，由玩家确认和编辑。可用日历：'+calCollections().map(x=>x.id+'='+x.name).join('；');}
function calPlayerPayload(p,c,turn){if(!p||typeof p!=='object'||Array.isArray(p))return null;const title=String(p.title||'').trim().slice(0,160),date=String(p.date||''),allDay=p.allDay===true,time=allDay?'':calTimeValue(p.time),endTime=allDay?'':calTimeValue(p.endTime),endDate=p.endDate||date;if(!title||!roleCalDateValid(date)||!allDay&&!time||!roleCalDateValid(endDate)||endDate<date||!allDay&&endDate!==date&&!endTime||p.endTime&&!allDay&&!endTime||endTime&&new Date(endDate+'T'+endTime)<=new Date(date+'T'+time))return null;const calendarId=String(p.calendarId||'');if(calendarId&&!calCollection(calendarId))return null;const keys={none:'none',day:'daily',week:'weekly',biweekly:'biweekly',month:'monthly',year:'yearly'},repeatKey=keys[p.repeat||'none'];if(!repeatKey)return null;const lead=p.alertMinutes==null?-1:+p.alertMinutes;if(!CAL_ALERT_OPTIONS.some(x=>x[0]===lead))return null;const e={id:uid(),owner:actId(),editorVersion:1,type:'event',title,date,time,allDay,endDate,endTime,repeat:calRepeatRule(repeatKey,{}),alertMinutes:lead,calendarId,location:String(p.location||'').slice(0,300),notes:String(p.notes||'').slice(0,5000),invitees:lead>=0?[c.id]:[],roleParticipation:lead>=0?{[c.id]:{mode:'remind',response:'accepted',prepare:false,followup:false}}:{},contactId:c.id,createdBy:c.id,createdAt:Date.now(),revision:1};e.roleScheduleKey=actId()+'|'+c.id+'|'+String(turn)+'|'+JSON.stringify([e.date,e.time,e.title,e.endDate,e.endTime]);return e;}
async function calPlayerConsume(content,c,turn){const text=String(content||''),re=/^[ \t]*[\[【]\s*为你安排日程\s*[|｜]\s*(\{[^\n]*\})\s*[\]】][ \t]*$/gm,legacy=/[\[【]\s*日程\s*[|｜:：]\s*([^\]】]*)[\]】]/g,matches=[...text.matchAll(re)],old=[...text.matchAll(legacy)];if(!matches.length&&!old.length)return {text,changed:false};const clean=text.replace(re,'').replace(legacy,'').trim();if(!c||getC(c.id)!==c||c.deleted||c.blocked)return {text:clean,changed:false};const payloads=[];for(const m of matches){try{payloads.push(JSON.parse(m[1]));}catch(_){}}for(const m of old){const f=m[1].split(/[|｜:：]/);payloads.push({date:f.shift().trim(),title:f.join('｜').trim(),allDay:true});}const state=S,owner=actId(),events=[],cards=[],priorMessages=S.messages;let invalid=!payloads.length;for(const p of payloads){const e=calPlayerPayload(p,c,turn);if(!e){invalid=true;continue;}if((S.calendar||[]).concat(events).some(x=>x.roleScheduleKey===e.roleScheduleKey))continue;events.push(e);cards.push({id:uid(),role:'assistant',type:'calendarcreated',calendarOwner:owner,calendarRole:c.id,calendarEventId:e.id,time:Date.now()});}if(invalid)toast('日程信息不完整或无效，尚未完整保存');if(!events.length)return {text:invalid?'':clean,changed:false,failed:invalid};S.calendar=(S.calendar||[]).concat(events);S.messages={...priorMessages,[accountMessageKey(c.id,owner)]:msgs(c.id).concat(cards)};const ok=await calPersist();if(S!==state||actId()!==owner||getC(c.id)!==c)return {text:clean,changed:false,stale:true};if(!ok){const ids=new Set(events.map(e=>e.id));S.calendar=(S.calendar||[]).filter(e=>!ids.has(e.id));calRollbackCards(cards,c.id,owner,priorMessages);toast('日程保存失败，请重试');return {text:'',changed:false,failed:true};}cards.forEach(m=>notifyIncoming(c,m));if(cur().p==='chat'&&cur().id===c.id)refreshChatMessages(c.id);return {text:invalid?'':clean,changed:true,sent:cards.length};}
function calCreatedCardEvent(m){return m&&m.calendarOwner===actId()?(S.calendar||[]).find(e=>e.id===m.calendarEventId&&calEventOwned(e)&&e.createdBy===m.calendarRole)||null:null;}
function calCreatedCardOpen(id,cid,owner){const e=calCreatedCardEvent({calendarOwner:owner,calendarRole:cid,calendarEventId:id});if(!e||cur().p!=='chat'||cur().id!==cid){toast('这条日程已不可用');return;}calDetailOpen(id,e.date);}
