function roleCalPrompt(c){const rows=roleCalRows(c.id).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(-30);return calPlayerPrompt(c)+'\n\n# 你自己的日历\n这是你的个人记录，与玩家的日历独立。可按人设、已经建立的生活事实和对话，自主决定记录自己的计划，用 [我的日程|YYYY-MM-DD|HH:MM或全天|事项]；只记录你确实决定的事项，不为了回答而编造已有记录，不把玩家日程复制成你的行程。想把某天已记录的内容分享给玩家时，用 [分享我的日程|YYYY-MM-DD]，会实际发送可点击的日程卡片。玩家询问你当天安排时可以选择分享；平常是否主动分享也由你自己决定，没有必须分享的频率，不要声称未发送的卡片已发出。没有记录就如实说明。若真心想邀请玩家参加自己的一件安排，可以使用 [邀请你参加日程|YYYY-MM-DD|HH:MM或全天|事项]。这会发出可点击的邀请，玩家可接受、可能或拒绝；普通分享不等于邀请，不要替玩家决定答复。不能用这些标签编辑玩家已有日历。\n玩家对你的邀请答复：'+(S.calendar||[]).filter(e=>calEventOwned(e)&&e.invitedBy===c.id).map(e=>e.title+' '+calInvitationLabel(e.invitationStatus)).join('；')+'\n已记录：'+(rows.length?rows.map(e=>e.date+' '+(e.time||'全天')+' '+e.title).join('；'):'暂无记录');}
function roleCalDateValid(date){const p=calDateParts(date);return !!p&&p.y>=1900&&p.y<=2100&&p.m>=1&&p.m<=12&&p.d>=1&&new Date(p.y,p.m-1,p.d).getMonth()===p.m-1&&new Date(p.y,p.m-1,p.d).getDate()===p.d;}
