function roleCalCardRows(m){if(!m||m.calendarOwner!==actId()||!getC(m.calendarRole)||getC(m.calendarRole).deleted)return [];return roleCalRows(m.calendarRole).filter(e=>e.date===m.date&&(m.eventIds||[]).includes(e.id)).sort((a,b)=>(a.time||'').localeCompare(b.time||''));}
