function renderCalShared(route){let title='',rows=[],valid=route.owner===actId();if(valid&&route.kind==='invite'){const e=calInviteCardEvent({calendarOwner:route.owner,calendarEventId:route.eventId,calendarRecipient:route.cid});valid=!!e;rows=e?[e]:[];title=e?e.title:'日程邀请';}else if(valid&&route.kind==='role'){const m=msgs(route.cid).find(x=>x.id===route.mid&&x.type==='rolecalendarshare');rows=roleCalCardRows(m);valid=!!m&&rows.length>0;const c=getC(route.cid);title=c?(c.remark||c.name)+'的日程':'日程分享';}else if(valid){valid=calShareAllowed({calendarId:route.calendarId,calendarOwner:route.owner,calendarRecipient:route.cid});const c=valid&&calCollection(route.calendarId);title=c?c.name:'日历分享';rows=valid?(S.calendar||[]).filter(e=>e.calendarId===route.calendarId):[];}rows=rows.slice().sort((a,b)=>(a.date+' '+(a.time||'')).localeCompare(b.date+' '+(b.time||'')));return '<div class="cal-sheet-page cal-shared-page"><header class="cal-sheet-header"><button class="photo-album-glass cal-sheet-close" aria-label="返回聊天" onclick="back()">'+calIcon('back')+'</button><strong>'+esc(title||'日程分享')+'</strong><span></span></header><main class="cal-sheet-body">'+(!valid?'<div class="cal-sheet-empty">这份分享已不可用</div>':rows.length?'<h3>已分享的日程 · 只读</h3><section class="cal-sheet-group">'+rows.map(e=>'<div class="cal-sheet-row"><i class="cal-color-dot" style="background:'+calEventColor(e)+'"></i><span>'+esc(e.title)+'<small>'+esc(e.date)+' · '+esc(e.allDay?'全天':e.time||'全天')+(e.repeat&&e.repeat.unit!=='none'?' · '+esc(calRepeatLabel(e)):'')+'</small>'+(e.location?'<small>'+esc(e.location)+'</small>':'')+(e.notes?'<small class="cal-detail-notes">'+esc(e.notes)+'</small>':'')+(e.url&&/^https?:\/\//i.test(e.url)?'<small><a href="'+calAttr(e.url)+'" target="_blank" rel="noopener noreferrer">'+esc(e.url)+'</a></small>':'')+'</span></div>'+ (route.kind==='role'?calRoleInvitationButtons(route,e):'')).join('')+'</section>':'<div class="cal-sheet-empty">暂无日程</div>')+'</main></div>';}

