function calInviteFilter(value){if(_calSaving||_calPanelOwner!==actId())return;_calInviteSearch=String(value||'');const list=$('#cal_invite_choices');if(list)list.innerHTML=calInviteChoiceHTML();}
function calInviteChoiceHTML(){const q=_calInviteSearch.toLowerCase().trim(),roles=calInviteRoles().filter(c=>!q||(c.remark||c.name||'').toLowerCase().includes(q)||String(c.name||'').toLowerCase().includes(q));return roles.length?roles.map(c=>'<button class="cal-sheet-row cal-invite-choice" aria-label="选择受邀角色 '+calAttr(c.remark||c.name)+'" aria-pressed="'+_calEventInviteDraft.includes(c.id)+'" onclick="'+calCall('calInviteToggle',c.id)+'">'+av(c.avatar,'cal-invite-avatar')+'<span>'+esc(c.remark||c.name)+'</span><em class="cal-color-selected">'+(_calEventInviteDraft.includes(c.id)?calIcon('check'):'')+'</em></button>').join(''):'<div class="cal-sheet-empty">没有匹配的角色好友</div>';}
function renderCalInvite(){const pick=_calPanel==='eventInvitePick';return '<div class="cal-sheet-page"><header class="cal-sheet-header"><button class="photo-album-glass cal-sheet-close" aria-label="取消受邀人" onclick="calInviteCancel()">'+calIcon('close')+'</button><strong>'+(pick?'选择角色好友':'添加受邀人')+'</strong><button class="photo-album-glass cal-sheet-close cal-sheet-confirm" aria-label="确认受邀人" onclick="calInviteApply()">'+calIcon('check')+'</button></header><main class="cal-sheet-body cal-invite-body"><div class="cal-invite-recipient"><span>收件人：</span><input aria-label="搜索受邀角色" placeholder="角色昵称" value="'+calAttr(_calInviteSearch)+'" oninput="calInviteFilter(this.value)"><button class="photo-album-glass cal-invite-plus" aria-label="添加受邀角色" onclick="_calPanel=\'eventInvitePick\';render()">'+calIcon('plus')+'</button></div><div class="cal-invite-chips">'+_calEventInviteDraft.map(cid=>{const c=getC(cid);return c?'<button onclick="'+calCall('calInviteToggle',cid)+'">'+av(c.avatar,'cal-invite-avatar')+'<span>'+esc(c.remark||c.name)+'</span>'+calIcon('close')+'</button>':'';}).join('')+'</div>'+(pick||_calInviteSearch?'<section id="cal_invite_choices" class="cal-sheet-group">'+calInviteChoiceHTML()+'</section>':'<section id="cal_invite_choices"></section>')+'<p class="cal-new-note cal-invite-note">受邀角色只获得这条日程。添加后可选择只告知、一起参与或帮我提醒；默认只告知。</p></main></div>';}
function calInvitedEvent(e,cid){return !!e&&calEventOwned(e)&&(e.invitees||[]).includes(cid)&&calInviteRoles().some(c=>c.id===cid);}
function calInviteCardEvent(m){if(!m||m.calendarOwner!==actId())return null;const e=(S.calendar||[]).find(e=>e.id===m.calendarEventId);return calInvitedEvent(e,m.calendarRecipient)?e:null;}
function calInviteCardText(m){const e=calInviteCardEvent(m);return e?'[日程邀请] '+calEventFact(e)+'。参与方式：'+calParticipationLabel(e,m.calendarRecipient)+'。只告知时不催促，一起参与可以自由回应，帮我提醒才按设置提醒。':'[日程邀请已不可用]';}
function calInviteCardHTML(m){const e=calInviteCardEvent(m),c=e&&e.calendarId&&calCollection(e.calendarId),color=c?calColorValue(c.color):'#009aff';return '<button class="cal-share-card cal-share-rich" style="--cal-card-accent:'+(color||'#009aff')+'" onclick="event.stopPropagation();'+calCall('calInviteCardOpen',m.calendarEventId,m.calendarRecipient,m.calendarOwner)+'"><span class="cal-card-head"><span class="cal-card-icon">'+calIcon('calendar')+'</span><span class="cal-card-kind">日程邀请</span></span><strong>'+esc(e?e.title:'日程邀请已不可用')+'</strong><span class="cal-card-meta">'+esc(e?e.date+' · '+(e.allDay?'全天':e.time):'邀请已取消或账户不同')+'</span><span class="cal-card-footer"><span>'+esc(e?(S.me.name||'用户')+' 邀请 '+calRoleName(m.calendarRecipient):'分享不可用')+'</span><span>'+(e?'查看 '+calIcon('chevron'):'')+'</span></span></button>';}
function calInviteCardOpen(eventId,cid,owner){const m={calendarOwner:owner,calendarEventId:eventId,calendarRecipient:cid};if(cur().p!=='chat'||cur().id!==cid||!calInviteCardEvent(m)){toast('这条日程邀请不可用');return;}go('calendarShared',{kind:'invite',eventId,cid,owner});}

function calInvitationLabel(status){return {pending:'尚未答复',accepted:'已接受',tentative:'可能参加',declined:'已拒绝'}[status]||'尚未答复';}
function calInvitationButtons(e){if(!e||!e.invitedBy||!calEventOwned(e))return '';return '<section class="cal-sheet-group cal-invitation-response"><div class="cal-sheet-row"><span>'+esc(calRoleName(e.invitedBy))+'的邀请<small>'+calInvitationLabel(e.invitationStatus)+'</small></span></div><div class="cal-invitation-actions">'+[['accepted','接受'],['tentative','可能'],['declined','拒绝']].map(x=>'<button aria-label="'+x[1]+'日程邀请" aria-pressed="'+(e.invitationStatus===x[0])+'" onclick="'+calCall('calInvitationRespond',e.id,x[0])+'">'+x[1]+'</button>').join('')+'</div></section>';}
function calRoleInvitationButtons(route,r){const m=msgs(route.cid).find(x=>x.id===route.mid&&x.type==='rolecalendarshare'&&x.calendarInvitation),e=m&&m.calendarOwner===actId()&&(m.eventIds||[]).includes(r.id)&&(S.calendar||[]).find(e=>calEventOwned(e)&&e.invitedBy===route.cid&&e.sourceRoleEvent===r.id);return e?calInvitationButtons(e):'';}
async function calInvitationRespond(id,status){if(_calSaving||!['accepted','tentative','declined'].includes(status))return;const e=(S.calendar||[]).find(e=>e.id===id&&calEventOwned(e)&&e.invitedBy),role=e&&getC(e.invitedBy);if(!e||!role||role.deleted||role.blocked)return;const state=S,owner=actId(),old={status:e.invitationStatus,declined:e.declined,alert:e.alertMinutes,revision:e.alertRevision};_calSaving=true;e.invitationStatus=status;e.declined=status==='declined';e.alertMinutes=e.declined?-1:0;e.alertRevision=(+e.alertRevision||0)+1;const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){e.invitationStatus=old.status;e.declined=old.declined;e.alertMinutes=old.alert;e.alertRevision=old.revision;toast('答复保存失败');return;}render();toast(calInvitationLabel(status));}

function calRoleInvitedText(cid){const invited=(S.calendar||[]).filter(e=>calInvitedEvent(e,cid));if(!invited.length)return '';return invited.map(e=>'ID='+e.id+' · '+calEventFact(e)+' · '+calParticipationLabel(e,cid)+' · 完成情况：'+(e.completed?'玩家确认完成':(e.completedDates||[]).length?'已完成日期 '+e.completedDates.join('、'):'尚未确认完成')).join('\n')+'\n收到邀请可按自己意愿用 [回应日程邀请|日程ID|accepted或tentative或declined] 表达愿意、待定或拒绝（用英文状态值）。只告知不催促；一起参与先讨论，不假装已同意；帮我提醒按设置。可以建议调整但不能自己改时间、删除或标记完成。';}
function calInviteNoteValid(note,cid,owner){const matches=[...String(note||'').matchAll(/\[日程受邀提醒作用域\|([^\]]+)\]/g)];return matches.every(match=>{try{const meta=JSON.parse(decodeURIComponent(match[1]));if(meta.stage)return calCareValid(meta,cid,owner);const e=(S.calendar||[]).find(x=>x.id===meta.eventId),c=e&&e.calendarId&&calCollection(e.calendarId),now=Date.now(),start=e&&calEventLocalAt(e,meta.date)-meta.lead*60000,until=e&&calEventLocalAt({...e,endDate:calAddDays(meta.date,calDayDiff(e.endDate||e.date,e.date))},meta.date,true);return now>=start&&now<=until&& meta.owner===owner&&owner===actId()&&meta.roleId===cid&&(+meta.revision||0)===(+e.revision||0)&&calInvitedEvent(e,cid)&&calRoleCanRemind(e,cid)&&(!c||c.alerts!==false)&&!e.completed&&!(e.completedDates||[]).includes(meta.date)&&(e.alertMinutes>=0?e.alertMinutes:0)===meta.lead&&calOccurrenceStarts(e,meta.date,meta.date).length===1;}catch(_){return false;}});}
function calInviteReminderNote(e,cid,date){const lead=e.alertMinutes>=0?e.alertMinutes:0,scope=encodeURIComponent(JSON.stringify({owner:actId(),eventId:e.id,roleId:cid,date,lead,revision:+e.revision||0}));return featureEventNote('受邀日程提醒','这是'+S.me.name+'明确邀请你参与并让你提醒的一条日程；本轮提醒已经到时。事项：'+calEventFact({...e,date})+'。'+(e.endTime?'结束时间：'+e.endTime+'。':'')+(e.travelMinutes?calDepartureText(e,date)+'。':'')+'只读这条受邀记录，不能自行读取同日历未共享的其他事项。先自然回应眼前这件事，可以按你的人设关心、询问准备情况或提出具体建议，不要念固定模板，不要强制温柔、重复催促或说自己已经完成用户的事项。不要重复旧话题或添加未记录的时间地点。')+'\n[日程受邀提醒作用域|'+scope+']';}
function calFireInvitedReminders(now){now=Number.isFinite(+now)?+now:Date.now();const state=S,owner=actId(),today=calDateString(new Date(now)),keys=S.calendarRoleFired||{};(S.calendar||[]).filter(e=>e.editorVersion===1&&calEventOwned(e)&&!e.completed).forEach(e=>{const collection=e.calendarId&&calCollection(e.calendarId);if(collection&&collection.alerts===false)return;calOccurrenceStarts(e,today,calAddDays(today,8)).forEach(date=>{if((e.completedDates||[]).includes(date))return;const lead=e.alertMinutes>=0?e.alertMinutes:0,at=calEventLocalAt(e,date)-lead*60000,until=calEventLocalAt({...e,endDate:calAddDays(date,calDayDiff(e.endDate||e.date,e.date))},date,true);if(!Number.isFinite(at)||now<at||now>until)return;(e.invitees||[]).forEach(cid=>{const key=owner+'|'+e.id+'|'+date+'|'+lead+'|v'+(+e.alertRevision||0)+'|'+cid;if(keys[key]||_calInvitedBusy[key]&&Date.now()-_calInvitedBusy[key]<180000||!calInvitedEvent(e,cid)||!calRoleCanRemind(e,cid)||roleOnlineProactiveBlocked(cid))return;const note=calInviteReminderNote(e,cid,date);_calInvitedBusy[key]=Date.now();let settled=false;const done=async ok=>{if(settled)return;settled=true;delete _calInvitedBusy[key];if(!ok||S!==state||actId()!==owner||!calInviteNoteValid(note,cid,owner))return;S.calendarRoleFired=S.calendarRoleFired||{};S.calendarRoleFired[key]=Date.now();await calPersist();};if(!scheduleFeatureReply(cid,note,0,done,owner))done(false);});});});}

/* Personal checklist editor and detail pages backed by the actual saved record. */
function calReminderDateToggle(){if(!_calEventDraft||_calSaving)return;_calEventDraft.reminderHasDate=!_calEventDraft.reminderHasDate;if(!_calEventDraft.reminderHasDate){_calEventDraft.reminderHasTime=false;_calEventPicker='';}calNewRender();}
function calReminderTimeToggle(){if(!_calEventDraft||_calSaving)return;_calEventDraft.reminderHasTime=!_calEventDraft.reminderHasTime;if(_calEventDraft.reminderHasTime)_calEventDraft.reminderHasDate=true;else if(_calEventPicker==='time')_calEventPicker='';calNewRender();}
function calReminderFormHTML(d){const c=d.calendarId&&calCollection(d.calendarId),label=d.date===todayStr()?'今天':calDateDisplay(d.date),repeat=calRepeatRule(d.repeatKey,d.customRepeat);return '<section class="cal-sheet-group cal-new-title cal-reminder-title"><input aria-label="提醒事项标题" placeholder="标题" maxlength="160" value="'+calAttr(d.title)+'" oninput="calNewField(\'title\',this.value)"><textarea aria-label="提醒事项备注" placeholder="备注" maxlength="5000" oninput="calNewField(\'notes\',this.value)">'+esc(d.notes||'')+'</textarea></section><h3 class="cal-reminder-label">日期与时间</h3><section class="cal-sheet-group"><div class="cal-sheet-row cal-reminder-field'+(d.reminderHasDate?'':' inactive')+'"><span class="cal-reminder-glyph">'+calIcon('calendar')+'</span><button aria-label="提醒事项日期" onclick="'+(d.reminderHasDate?"calEditorPickerOpen('date')":"calReminderDateToggle()")+'"><strong>日期</strong><small>'+esc(d.reminderHasDate?label:'不设置日期')+'</small></button>'+calSwitch(d.reminderHasDate,'calReminderDateToggle()','设置提醒事项日期')+'</div>'+(d.reminderHasDate?calEditorPickerHTML('date'):'')+'<div class="cal-sheet-row cal-reminder-field'+(d.reminderHasTime?'':' inactive')+'"><span class="cal-reminder-glyph">'+calIcon('clock')+'</span><button aria-label="提醒事项时间" onclick="'+(d.reminderHasTime?"calEditorPickerOpen('time')":"calReminderTimeToggle()")+'"><strong>时间</strong><small>'+esc(d.reminderHasTime?d.time:'不设置时间')+'</small></button>'+calSwitch(d.reminderHasTime,'calReminderTimeToggle()','设置提醒事项时间')+'</div>'+(d.reminderHasTime?calEditorPickerHTML('time'):'')+'</section>'+(d.reminderHasDate?'<section class="cal-sheet-group">'+calNewOptionRow('重复',calRepeatLabel({repeat}),'repeat')+'</section>':'')+'<h3 class="cal-reminder-label">分类</h3><section class="cal-sheet-group">'+calNewOptionRow('日历',c?c.name:'默认待办','calendar',c?(calColorValue(c.color)||'#009aff'):'#009aff')+'</section><p class="cal-new-note">做完后勾选完成；重复待办只完成这一次。未设日期的待办显示在首页“未安排日期”中。'+(d.reminderHasTime?'到时在小手机运行时提醒。':'')+'</p>';}
function renderCalReminderPage(d){const state=S,owner=actId();queueMicrotask(()=>{const b=$('#cal_new_body');if(b&&S===state&&actId()===owner)b.scrollTop=_calNewScrollTop;});return '<div class="cal-sheet-page cal-new-page"><header class="cal-sheet-header"><button class="photo-album-glass cal-sheet-close" aria-label="取消新项目" onclick="calNewClose()">'+calIcon('close')+'</button><strong>'+(d._editId?'编辑提醒事项':'新项目')+'</strong><button class="photo-album-glass cal-sheet-close cal-sheet-confirm" aria-label="保存新项目" onclick="calNewSave()">'+calIcon('check')+'</button></header><main id="cal_new_body" class="cal-sheet-body cal-new-body">'+(!d._editId?'<div class="cal-picker-tabs cal-new-tabs"><button onclick="calNewType(\'event\')">日程</button><button class="selected" onclick="calNewType(\'reminder\')">提醒事项</button></div>':'')+calReminderFormHTML(d)+'</main>'+calNewPopover()+'</div>';}
function calUndatedReminders(){return (S.calendar||[]).filter(e=>e.type==='reminder'&&!e.date&&calEventVisible(e));}
function calReminderAgendaRow(e){return '<div class="cal-reminder-agenda cal-unified-reminder'+(e.completed?' completed':'')+'"><button class="cal-reference-event cal-reminder-agenda-main" aria-label="查看提醒事项 '+calAttr(e.title)+'" onclick="'+calCall('calEventOpen',e.id,e._occurrenceDate||e.date||'')+'"><i style="background:'+calEventColor(e)+'"></i><div><strong>'+esc(e.title||'未命名提醒事项')+'</strong>'+(e.notes?'<small>'+esc(String(e.notes).split('\n')[0])+'</small>':'')+'</div><time>'+esc(e.time||'待办')+'</time></button><button class="cal-complete-circle" aria-label="'+(e.completed?'标记未完成 ':'完成 ')+calAttr(e.title)+'" aria-pressed="'+!!e.completed+'" style="--cal-color:'+calEventColor(e)+'" onclick="event.stopPropagation();'+calCall('calReminderToggle',e.id,e._occurrenceDate||e.date||'')+'">'+(e.completed?calIcon('check'):'')+'</button></div>';}

function calUndatedReminderHTML(){const rows=calUndatedReminders();return rows.length?'<section class="cal-undated"><h3>未安排日期</h3>'+rows.map(calReminderAgendaRow).join('')+'</section>':'';}
function calDetailEvent(route){return route&&route.owner===actId()?(S.calendar||[]).find(e=>e.id===route.id&&calEventOwned(e)&&!(e.excludedDates||[]).includes(route.date))||null:null;}
function calDetailOpen(id,date){const e=(S.calendar||[]).find(e=>e.id===id&&calEventOwned(e));if(!e){calLegacyRecordsOpen();return;}go('calendarDetail',{id,date:roleCalDateValid(date)?date:e.date||'',owner:actId()});}
function calDetailClock(e,date){if(e.type==='reminder'&&e.reminderVersion===2)return e.time?'计划时间 '+e.time:'未设置具体时间';if(e.allDay||!e.time)return '全天';const last=e.endDate&&e.endDate!==e.date?calAddDays(date,calDayDiff(e.endDate,e.date)):'';return e.time+(e.endTime?' – '+(last?last+' ':'')+e.endTime:'');}
function calReminderDetailPoint(e){if(!e.time||!e.date)return '';const minutes=+e.time.slice(0,2)*60+(+e.time.slice(3)),from=Math.max(0,Math.floor(minutes/60)-1),to=Math.min(24,from+3),top=(minutes-from*60)/((to-from)*60)*100,ticks=[];for(let h=from;h<=to;h++)ticks.push('<div class="cal-detail-hour" style="top:'+(h-from)/(to-from)*100+'%"><span>'+String(h).padStart(2,'0')+':00</span><i></i></div>');return '<section class="cal-detail-timeline"><div>'+ticks.join('')+'<span class="cal-detail-point" style="top:'+top+'%;--cal-color:'+calEventColor(e)+'"><i></i><b>'+esc(e.title)+'</b></span></div></section>';}
function calDetailTimeline(e,date){if(e.type==='reminder'&&(e.reminderVersion===2||!e.endTime))return calReminderDetailPoint(e);if(e.allDay||!e.time||!e.endTime)return '';const start=+e.time.slice(0,2)*60+(+e.time.slice(3)),span=(+e.endTime.slice(0,2)*60+(+e.endTime.slice(3)))-start,multi=e.endDate&&e.endDate!==e.date,from=Math.max(0,Math.floor(start/60)-1),to=Math.min(24,Math.max(from+3,Math.ceil((start+Math.max(30,span))/60)+1)),range=(to-from)*60,top=Math.max(0,(start-from*60)/range*100),height=Math.max(.5,Math.min(100-top,(multi?1440-start:Math.max(1,span))/range*100)),ticks=[];for(let h=from;h<=to;h++)ticks.push('<div class="cal-detail-hour" style="top:'+(h-from)/(to-from)*100+'%"><span>'+String(h).padStart(2,'0')+':00</span><i></i></div>');return '<section class="cal-detail-timeline"><div>'+ticks.join('')+'<span class="cal-detail-block" style="top:'+top+'%;height:'+height+'%;background:'+calEventColor(e)+'">'+esc(e.title)+'</span></div></section>';}
function renderCalDetail(route){const e=calDetailEvent(route);if(!e)return '<div class="cal-month-page cal-detail-page"><header class="cal-reference-nav"><button class="photo-album-glass cal-glass cal-year" onclick="back()">'+calIcon('back')+'返回日历</button></header><div class="cal-sheet-empty">这条记录已删除或不属于当前账户</div></div>';const date=roleCalDateValid(route.date)&&calOccurrenceStarts(e,route.date,route.date).length?route.date:e.date||'',c=e.calendarId&&calCollection(e.calendarId),series=e.repeat&&e.repeat.unit!=='none',done=e.completed||(e.completedDates||[]).includes(date),weekday=roleCalDateValid(date)?['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][new Date(date+'T12:00').getDay()]:'',rows=[];rows.push('<div class="cal-sheet-row"><span>日历</span><i class="cal-color-dot" style="background:'+calEventColor(e)+'"></i><em>'+esc(c?c.name:e.type==='reminder'?'默认待办':'默认日历')+'</em></div>');if(e.type!=='reminder')rows.push('<div class="cal-sheet-row"><span>提醒</span><em>'+esc((CAL_ALERT_OPTIONS.find(x=>x[0]===e.alertMinutes)||CAL_ALERT_OPTIONS[0])[1])+'</em></div>');if(Array.isArray(e.excludedDates)&&e.excludedDates.length)rows.push('<div class="cal-sheet-row"><span>跳过日期</span><em>'+e.excludedDates.map(esc).join('、')+'</em></div>');if(e.location)rows.push('<div class="cal-sheet-row"><span>位置或视频通话</span><em>'+esc(e.location)+'</em></div>');if(e.travelMinutes)rows.push('<div class="cal-sheet-row"><span>行程时间</span><em>'+esc((CAL_TRAVEL_OPTIONS.find(x=>x[0]===e.travelMinutes)||[0,e.travelMinutes+'分钟'])[1])+'</em></div><div class="cal-sheet-row"><span>'+esc(calDepartureText(e,date))+'</span></div>');if((e.invitees||[]).length)rows.push('<div class="cal-sheet-row"><span>受邀人</span><em>'+e.invitees.map(id=>esc(calRoleName(id))).join('、')+'</em></div>');if(e.url&&/^https?:\/\//i.test(e.url))rows.push('<div class="cal-sheet-row"><a href="'+calAttr(e.url)+'" target="_blank" rel="noopener noreferrer">'+esc(e.url)+'</a></div>');if(e.notes)rows.push('<div class="cal-sheet-row"><span class="cal-detail-notes">'+esc(e.notes)+'</span></div>');return '<div class="cal-month-page cal-detail-page"><header class="cal-reference-nav"><button class="photo-album-glass cal-glass cal-year" aria-label="返回日历首页" onclick="back()">'+calIcon('back')+'<span>'+esc(roleCalDateValid(date)?calMonthName(calDateParts(date).m):'日历')+'</span></button>'+(['event','reminder'].includes(e.type)&&!e.invitedBy?'<button class="photo-album-glass cal-glass cal-detail-edit" aria-label="编辑记录" onclick="'+calCall('calDetailEdit',e.id)+'">编辑</button>':'')+'</header><main class="cal-detail-scroll"><h1>'+esc(e.title||'未命名记录')+'</h1><p class="cal-detail-date">'+esc(date?calDateDisplay(date)+' '+weekday:'未安排日期')+'<br>'+esc(calDetailClock(e,date))+'</p>'+(series?'<p class="cal-detail-repeat">'+esc(calRepeatLabel(e))+'</p>':'')+calDetailTimeline(e,date)+'<section class="cal-sheet-group">'+rows.join('')+'</section>'+calParticipationHTML(e,false)+calInvitationButtons(e)+(e.type==='event'&&!e.invitedBy?'<button class="photo-album-glass cal-glass cal-detail-complete" onclick="'+calCall('calEventOutcome',e.id,date)+'">'+((e.completedDates||[]).includes(date)?'已完成 · 撤销确认':'确认这次已完成')+'</button>':'')+(e.type==='reminder'?'<button class="cal-detail-complete" onclick="'+calCall('calReminderToggle',e.id,date)+'">'+(done?'标记为未完成':'标记为完成')+'</button>':'')+'<button class="photo-album-glass cal-glass cal-detail-delete" onclick="'+calCall('calDetailDeleteAsk',e.id,date)+'">删除'+(e.type==='reminder'?'提醒事项':'日程')+'</button></main></div>';}
function calDetailEdit(id){const e=(S.calendar||[]).find(e=>e.id===id&&calEventOwned(e));if(!e||e.invitedBy||!['event','reminder'].includes(e.type)||_calSaving)return;const key=e.repeat&&e.repeat.unit!=='none'?(CAL_REPEAT_OPTIONS.find(x=>!['custom','none'].includes(x[0])&&JSON.stringify(calRepeatRule(x[0],{}))===JSON.stringify(e.repeat))||['custom'])[0]:'none';_calPanelOwner=actId();_calEventDraft={...JSON.parse(JSON.stringify(e)),_editId:e.id,_editRevision:+e.revision||0,title:e.title||'',notes:e.notes||'',location:e.location||'',url:e.url||'',date:e.date||todayStr(),endDate:e.endDate||e.date||todayStr(),time:e.time||'09:00',endTime:e.endTime||'',_preserveNoEnd:!e.endTime,allDay:!!e.allDay||!e.time,travelMinutes:e.travelMinutes||0,repeatKey:key,customRepeat:e.repeat&&e.repeat.unit!=='none'?e.repeat:{unit:'week',interval:1,until:''},calendarId:e.calendarId||'',invitees:(e.invitees||[]).slice(),alertMinutes:e.alertMinutes==null?-1:e.alertMinutes,reminderHasDate:!!e.date,reminderHasTime:!!e.time,_legacyReminder:e.type==='reminder'&&e.reminderVersion!==2};_calPanel='newEvent';_calEventPicker='';_calEventMenu='';_calNewScrollTop=0;go('calendar');}
