function calSearchInput(value){_calSearchQuery=String(value||'').slice(0,200);_calSearchLimit=100;clearTimeout(_calSearchTimer);const state=S,owner=actId();_calSearchTimer=setTimeout(()=>{if(S===state&&actId()===owner)calSearchRefresh();},100);}
function calSearchClear(){_calSearchQuery='';const field=$('#cal_search_input');if(field){field.value='';field.focus();}calSearchRefresh();}
function renderCalSearch(){if(_calSearchOwner!==actId()){_calSearchOpen=false;_calSearchQuery='';return renderCalendar();}if(_calSearchFocus){const state=S,owner=actId();queueMicrotask(()=>{if(S===state&&actId()===owner&&_calSearchOpen){const field=$('#cal_search_input');if(field)field.focus();}_calSearchFocus=false;});}return '<div class="cal-month-page cal-search-page"><header class="cal-search-nav"><div class="photo-album-glass cal-glass cal-search-field">'+calIcon('search')+'<input id="cal_search_input" type="search" aria-label="搜索日程和待办" placeholder="搜索" value="'+calAttr(_calSearchQuery)+'" oninput="calSearchInput(this.value)" autocomplete="off"><button id="cal_search_clear" aria-label="清空搜索" onclick="calSearchClear()"'+(!_calSearchQuery?' hidden':'')+'>'+calIcon('close')+'</button></div><button class="photo-album-glass cal-glass cal-search-close" aria-label="关闭搜索" onclick="calSearchClose()">'+calIcon('close')+'</button></header><main id="cal_search_results" class="cal-search-results" aria-live="polite">'+calSearchResultsHTML()+'</main><footer class="cal-reference-footer"><button class="photo-album-glass cal-glass cal-today" onclick="calToday()">今天</button><button class="photo-album-glass cal-glass cal-records" aria-label="日历记录管理" onclick="calRecordsOpen()">'+calIcon('calendar')+'</button></footer></div>';}

function calRecordsOpen(){calPanelOpen();}

let _calMonth='',_calSelected='',_calClockDay='';
function calDateParts(s){const m=String(s||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?{y:+m[1],m:+m[2],d:+m[3]}:null;}
function calDateString(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function calEnsure(){const today=todayStr();if(!_calMonth||_calClockDay!==today){_calMonth=today.slice(0,7);_calSelected=today;_calClockDay=today;}if(!calDateParts(_calSelected))_calSelected=today;}
function calSelect(date){if(calInputClock()<_calIgnoreClickUntil||!calDateParts(date))return;_calYearView=false;_calSelected=date;_calMonth=date.slice(0,7);render();}
function calShift(step){calEnsure();const p=calDateParts(_calSelected),mp=calDateParts(_calMonth+'-01'),day=p?p.d:1,last=new Date(mp.y,mp.m+(+step||0),0),next=new Date(last.getFullYear(),last.getMonth(),Math.min(day,last.getDate()));_calSelected=calDateString(next);_calMonth=_calSelected.slice(0,7);render();}
function calToday(){_calClockDay='';calEnsure();_calYearView=false;_calDayView=true;_calDayFirstWeek=calAddDays(calWeekStart(_calSelected),-14);_calDayAutoScroll=true;_calDayFocusMinute=null;_calSearchOpen=false;_calSearchQuery='';_calSearchFocus=false;render();}
function calLocate(){if(_calSaving)return;calEnsure();_calPanelOwner=actId();_calJumpMonth=_calSelected.slice(0,7);_calPanel='locate';render();}
function calLocateGo(){const el=$('#cal_locate_date'),v=el&&el.value;if(!calDateParts(v)){toast('请选择日期');return;}closeModal();_calPanel='';_calDraft=null;calSelect(v);}
function calWeekLabel(date){const p=calDateParts(date);return p?'星期'+'日一二三四五六'[new Date(p.y,p.m-1,p.d).getDay()]:'';}
function calUtcValue(s){const p=calDateParts(s);return p?Date.UTC(p.y,p.m-1,p.d):NaN;}
function calDayDiff(a,b){const av=calUtcValue(a),bv=calUtcValue(b);return Number.isFinite(av)&&Number.isFinite(bv)?Math.round((av-bv)/86400000):NaN;}
function calAddDays(s,n){const p=calDateParts(s);if(!p)return'';const d=new Date(Date.UTC(p.y,p.m-1,p.d+(+n||0)));return d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0')+'-'+String(d.getUTCDate()).padStart(2,'0');}
function periodStore(){if(!Array.isArray(S.periods))S.periods=[];return S.periods;}
function periodNormalize(p){if(!p||!calDateParts(p.startDate))return null;const hadEnd=Object.prototype.hasOwnProperty.call(p,'endDate'),end=calDateParts(p.endDate)?p.endDate:(hadEnd?'':p.startDate);if(end&&calDayDiff(end,p.startDate)<0)return null;return Object.assign(p,{endDate:end});}
function periodRecords(){return periodStore().map(periodNormalize).filter(p=>p&&(!p.owner||typeof actId==='function'&&p.owner===actId())).sort((a,b)=>a.startDate.localeCompare(b.startDate));}
function periodEffectiveEnd(p){if(p&&calDateParts(p.endDate))return p.endDate;const today=todayStr();return p&&calDayDiff(today,p.startDate)>=0?today:(p&&p.startDate||today);}
function periodForDate(date){return periodRecords().filter(p=>calDayDiff(date,p.startDate)>=0&&calDayDiff(periodEffectiveEnd(p),date)>=0);}
function periodEstimate(){const rows=periodRecords();if(!rows.length||!rows[rows.length-1].endDate)return null;let cycle=28;if(rows.length>1){const gaps=[];for(let i=Math.max(1,rows.length-4);i<rows.length;i++){const n=calDayDiff(rows[i].startDate,rows[i-1].startDate);if(n>=20&&n<=45)gaps.push(n);}if(gaps.length)cycle=Math.round(gaps.reduce((a,b)=>a+b,0)/gaps.length);}const last=rows[rows.length-1];return {date:calAddDays(last.startDate,cycle),cycle,last};}
function periodFactsText(){const rows=periodRecords();if(!rows.length)return'';const today=todayStr(),last=rows[rows.length-1],ongoing=!last.endDate&&calDayDiff(today,last.startDate)>=0,previous=rows.length>1?rows[rows.length-2]:null,est=periodEstimate();if(ongoing)return '本次经期于'+last.startDate+'开始，目前仍在进行、还没有记录结束日期；今天是第'+(calDayDiff(today,last.startDate)+1)+'天';if(!last.endDate)return '已记录经期将于'+last.startDate+'开始，目前没有结束日期';const duration=calDayDiff(last.endDate,last.startDate)+1,gap=previous&&previous.endDate?calDayDiff(last.startDate,previous.endDate)-1:null,current=calDayDiff(today,last.startDate)>=0&&calDayDiff(last.endDate,today)>=0;let t='最近一次：'+last.startDate+'开始，'+last.endDate+'结束，共'+duration+'天';if(Number.isFinite(gap))t+='；距离上一次结束间隔'+gap+'天';if(current)t+='；今天处于本次记录的第'+(calDayDiff(today,last.startDate)+1)+'天';if(est)t+='；按现有记录粗略估计下次约在'+est.date+'前后（只是估计，不是确定日期）';return t;}
function periodSummaryCard(){const rows=periodRecords(),est=periodEstimate();if(!rows.length)return `<section class="cal-agenda" style="background:linear-gradient(135deg,#fff2f6,#ffe6ef)"><div class="cal-agenda-title"><div><strong style="color:#b43d69">经期记录</strong><span>可以先记录开始日期，结束后再补准确日期</span></div><button onclick="addCalEvent('${todayStr()}','period')">记录开始</button></div><div class="cal-empty" style="color:#a77387">还没有经期记录</div></section>`;const last=rows[rows.length-1],ongoing=!last.endDate,days=calDayDiff(periodEffectiveEnd(last),last.startDate)+1,prev=rows.length>1?rows[rows.length-2]:null,gap=!ongoing&&prev&&prev.endDate?calDayDiff(last.startDate,prev.endDate)-1:null;return `<section class="cal-agenda" style="background:linear-gradient(135deg,#fff2f6,#ffe6ef);border-color:rgba(218,91,137,.16)"><div class="cal-agenda-title"><div><strong style="color:#b43d69">经期记录</strong><span>${last.startDate} ${ongoing?'开始 · 进行中第 '+days+' 天':'至 '+last.endDate+' · '+days+'天'}</span></div><button onclick="${ongoing?`periodEndModal('${last.id}')`:`addCalEvent('${todayStr()}','period')`}">${ongoing?'记录结束':'记录本次'}</button></div><div style="padding:0 4px 4px;color:#9c6077;font-size:12px;line-height:1.7">${ongoing?'角色已经知道本次开始；补上结束日期后也会知道实际持续天数。':(Number.isFinite(gap)?'距上一次结束 '+gap+' 天 · ':'')+(est?'预计下次约在 '+est.date+' 前后':'记录两次后可估算周期')}<br><span style="color:#b98799">预测只依据你的历史记录，用于生活提醒，不作医疗判断。</span></div></section>`;}
function calDelete(id){S.calendar=S.calendar.filter(x=>x.id!==id);save();render();}
function calDeletePeriod(id){askConfirm('删除这一整段经期记录？',()=>{S.periods=periodStore().filter(x=>x.id!==id);save();render()},{danger:true});}
function periodEndModal(id){const p=periodRecords().find(x=>x.id===id);if(!p||p.endDate)return;openModal(`<h3>记录经期结束</h3><div class="hint" style="margin-bottom:12px">开始日期：${esc(p.startDate)}。补上准确结束日期后，角色会知道本次已经结束和实际持续天数。</div><div class="field"><label>结束日期（含当天）</label><input id="period_end_date" type="date" value="${todayStr()}"></div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="periodEndSave('${p.id}')">保存结束日期</button></div>`);}
function periodEndSave(id){const p=periodRecords().find(x=>x.id===id),end=($('#period_end_date')||{}).value;if(!p||!calDateParts(end)||calDayDiff(end,p.startDate)<0){toast('结束日期不能早于开始日期');return;}p.endDate=end;p.endedAt=Date.now();save();closeModal();render();toast('经期结束日期已记录，角色也会知道');}
function calEventRow(e){const c=getC(e.contactId),period=e.type==='period',wedding=e.type==='wedding',del=period&&e._periodId?`calDeletePeriod('${e._periodId}')`:`calDelete('${e.id}')`,kind=wedding?'婚礼预约':period?'生理期':'日程',detail=wedding&&e.time?e.time+' · '+kind:kind;return `<div class="cal-event"><i style="background:${wedding?'#b89378':period?'#ff5b78':'#4b8cff'}"></i><div class="cal-event-main"><b>${esc(e.title)}</b><small>${period?(e._periodDay?'生理期 · 第'+e._periodDay+'天':'生理期'):esc(detail)}${c?' · '+esc(c.remark||c.name)+(wedding?'赴约':'提醒'):''}</small></div><button onclick="${del}" aria-label="删除日程">${svgIc('trash',17,'currentColor')}</button></div>`;}

let _calMonthScrollTimer=0,_calMonthQueued=false,_calLunarFormatter=null,_calLunarUnavailable=false;
const _calLunarLabels=new Map();
function calMonthName(n){return ['一','二','三','四','五','六','七','八','九','十','十一','十二'][n-1]+'月';}
function calMonthRows(month){const p=calDateParts(month+'-01'),first=new Date(p.y,p.m-1,1),days=new Date(p.y,p.m,0).getDate();return Math.ceil(((first.getDay()+6)%7+days)/7);}
function calRowHeight(){return typeof window==='undefined'?59:Math.max(48,Math.min(65,window.innerWidth*59/390));}
function calMonthHeight(month){return 61+calRowHeight()*calMonthRows(month);}
function calLunarLabel(date){if(_calLunarLabels.has(date))return _calLunarLabels.get(date);let result={text:'',monthStart:false};try{if(!_calLunarFormatter&&!_calLunarUnavailable){_calLunarFormatter=new Intl.DateTimeFormat('zh-CN-u-ca-chinese',{month:'long',day:'numeric',timeZone:'UTC'});if(_calLunarFormatter.resolvedOptions().calendar!=='chinese'){_calLunarUnavailable=true;_calLunarFormatter=null;}}if(_calLunarFormatter){const p=calDateParts(date),parts=_calLunarFormatter.formatToParts(new Date(Date.UTC(p.y,p.m-1,p.d,12))),day=+(parts.find(x=>x.type==='day')||{}).value,month=(parts.find(x=>x.type==='month')||{}).value||'',digits=['','一','二','三','四','五','六','七','八','九','十'];if(day>=1&&day<=30){result={text:day===1?month:day<=10?'初'+digits[day]:day<20?'十'+digits[day-10]:day===20?'二十':day<30?'廿'+digits[day-20]:'三十',monthStart:day===1};}}}catch(_){_calLunarUnavailable=true;}if(_calLunarLabels.size>800)_calLunarLabels.clear();_calLunarLabels.set(date,result);return result;}
function calEventsByYear(year){const byDate={},first=year+'-01-01',last=year+'-12-31';(S.calendar||[]).forEach(e=>calExpandedEvents(e,first,last).forEach(item=>(byDate[item.date]||(byDate[item.date]=[])).push(item)));(calPrefs().periodVisible===false?[]:periodRecords()).forEach(p=>{const end=periodEffectiveEnd(p),from=p.startDate<first?first:p.startDate,to=end>last?last:end;if(from>to)return;const days=calDayDiff(to,from)+1;for(let i=0;i<days;i++){const date=calAddDays(from,i);(byDate[date]||(byDate[date]=[])).push({id:'period-day-'+p.id+'-'+date,_periodId:p.id,_periodDay:calDayDiff(date,p.startDate)+1,date,title:p.title||'生理期',type:'period',contactId:p.contactId||''});}});return byDate;}
function calIcon(kind){const shapes={clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6H7"/>',menu:'<path d="m8 8 4-4 4 4M8 16l4 4 4-4"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',check:'<path d="m4 12 5 6 11-14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',person:'<circle cx="12" cy="5.5" r="3.7"/><path d="M4 21v-2a8 8 0 0 1 16 0v2Z"/>',back:'<path d="m15 4-8 8 8 8"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 6 6"/>',plus:'<path d="M12 3v18M3 12h18"/>',calendar:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 8h18"/><path d="M7 11h.1M12 11h.1M17 11h.1M7 15h.1M12 15h.1M17 15h.1M7 18h.1M12 18h.1M17 18h.1"/>',location:'<circle cx="12" cy="12" r="9"/><path d="m8 12 8-4-4 8-1-3Z"/>'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(shapes[kind]||shapes.calendar)+'</svg>';}
function calDevelopment(name){toast(name+' · 开发中');}
function calTimeValue(value){return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(value||''))?String(value):'';}
function calEventColor(e){const c=e.calendarId&&calCollection(e.calendarId);if(c)return /^#[0-9a-f]{6}$/i.test(c.color||'')?c.color:'#009aff';return /^#[0-9a-f]{6}$/i.test(e.color||'')?e.color:e.type==='period'?'#ff5b78':e.type==='wedding'?'#ad90c5':'#177d9f';}
function calAgendaHTML(date,byDate){const rows=(byDate[date]||[]).slice().sort((a,b)=>{const x=calTimeValue(a.time||a.startTime),y=calTimeValue(b.time||b.startTime);return x.localeCompare(y)||String(a.title||'').localeCompare(String(b.title||''));});if(!rows.length)return calUndatedReminders().length?calUndatedReminderHTML():'<div class="cal-reference-empty">无日程</div>';return rows.map(e=>{if(e.type==='reminder')return calReminderAgendaRow(e);const time=calTimeValue(e.time||e.startTime),end=calTimeValue(e.endTime),suggested=typeof e.suggestedLocation==='string'?e.suggestedLocation:'',location=suggested||e.location||e.place||'',detail=location?(suggested?'建议位置：':'位置：')+location:e.type==='period'?(e._periodDay?'生理期 · 第'+e._periodDay+'天':'生理期'):e.type==='wedding'?'约定婚礼':'';return '<button class="cal-reference-event" onclick="'+calCall('calEventOpen',e.id,e._occurrenceDate||e.date)+'" aria-label="日程详情"><i style="background:'+calEventColor(e)+'"></i><div><strong>'+esc(e.title||'未命名日程')+'</strong>'+(detail?'<small>'+(location?calIcon('location'):'')+esc(detail)+'</small>':'')+'</div><time>'+esc(time||'全天')+(end?'<span>'+esc(end)+'</span>':'')+'</time></button>';}).join('')+calUndatedReminderHTML();}
function calMonthSection(month,byDate,today){const p=calDateParts(month+'-01'),offset=(new Date(p.y,p.m-1,1).getDay()+6)%7,days=new Date(p.y,p.m,0).getDate(),cells=[];for(let i=0;i<calMonthRows(month)*7;i++){const day=i-offset+1;if(day<1||day>days){cells.push('<span class="cal-month-blank" aria-hidden="true"></span>');continue;}const date=month+'-'+String(day).padStart(2,'0'),lunar=calLunarLabel(date),events=byDate[date]||[];cells.push('<button class="cal-day'+(i%7>=5?' cal-weekend':'')+(date===today?' today':'')+(date===_calSelected?' selected':'')+'" data-cal-date="'+date+'" aria-pressed="'+(date===_calSelected)+'" aria-label="'+date+'，'+lunar.text+'，'+events.length+'项日程" onclick="calSelect(\''+date+'\')"><div class="cal-date-stack"><strong>'+day+'</strong><small class="'+(lunar.monthStart?'cal-lunar-month':'')+'">'+esc(lunar.text)+'</small></div>'+(events.length?'<i class="cal-dot'+(events.length>1?' multiple':'')+'" style="background:'+calEventColor(events[0])+'"></i>':'')+'</button>');}return '<section class="cal-month-section" data-cal-month="'+month+'" style="height:'+calMonthHeight(month)+'px"><h1>'+calMonthName(p.m)+'</h1><div class="cal-week">'+['一','二','三','四','五','六','日'].map((x,i)=>'<span class="'+(i>=5?'cal-weekend':'')+'">'+x+'</span>').join('')+'</div><div class="cal-grid">'+cells.join('')+'</div></section>';}
function calQueueMonthScroll(){if(typeof document==='undefined'||_calMonthQueued)return;_calMonthQueued=true;const state=S,owner=typeof actId==='function'?actId():'';queueMicrotask(()=>{_calMonthQueued=false;requestAnimationFrame(()=>{if(S!==state||typeof actId==='function'&&actId()!==owner||typeof cur==='function'&&cur().p!=='calendar')return;const box=document.getElementById('cal_month_scroll'),section=box&&box.querySelector('[data-cal-month="'+_calMonth+'"]');if(section){box.style.height=calMonthHeight(_calMonth)+'px';box.scrollTop=section.offsetTop;}});});}
function calMonthScrolled(){clearTimeout(_calMonthScrollTimer);_calMonthScrollTimer=setTimeout(()=>{const box=typeof document==='undefined'?null:document.getElementById('cal_month_scroll');if(!box||typeof cur==='function'&&cur().p!=='calendar')return;const section=Array.from(box.children).reduce((best,x)=>!best||Math.abs(x.offsetTop-box.scrollTop)<Math.abs(best.offsetTop-box.scrollTop)?x:best,null);if(!section||section.dataset.calMonth===_calMonth)return;const previous=calDateParts(_calSelected),month=section.dataset.calMonth,p=calDateParts(month+'-01');_calMonth=month;_calSelected=month+'-'+String(Math.min(previous?previous.d:1,new Date(p.y,p.m,0).getDate())).padStart(2,'0');box.style.height=calMonthHeight(month)+'px';box.querySelectorAll('[data-cal-date]').forEach(button=>{const yes=button.dataset.calDate===_calSelected;button.classList.toggle('selected',yes);button.setAttribute('aria-pressed',String(yes));});const agenda=document.getElementById('cal_day_agenda');if(agenda)agenda.innerHTML=calAgendaHTML(_calSelected,calEventsByYear(p.y));},90);}

let _calPeriodDraft=null,_calJumpMonth='';
function calPeriodOpen(id){if(_calSaving)return;_calPanelOwner=actId();const p=id&&periodRecords().find(x=>x.id===id);if(id&&!p)return;_calPeriodDraft=p?{...p}:null;_calPanel=p?'periodEdit':'periods';closeModal();render();}
function calPeriodNew(){if(_calSaving)return;_calPeriodDraft={id:uid(),startDate:_calSelected&&_calSelected<=todayStr()?_calSelected:todayStr(),endDate:'',title:'生理期',contactId:''};_calPanel='periodEdit';render();}
function calPeriodField(key,value){if(_calPeriodDraft&&!_calSaving&&_calPanelOwner===actId()&&['startDate','endDate','title','contactId'].includes(key))_calPeriodDraft[key]=value;}
async function calPeriodSave(){if(!_calPeriodDraft||_calSaving||_calPanelOwner!==actId())return;const d={..._calPeriodDraft},state=S,owner=actId();if(!roleCalDateValid(d.startDate)||d.endDate&&(!roleCalDateValid(d.endDate)||d.endDate<d.startDate)){toast('请填写有效日期，结束不能早于开始');return;}if(d.startDate>todayStr()||d.endDate&&d.endDate>todayStr()){toast('实际经期记录不能晚于今天');return;}if(periodRecords().some(p=>p.id!==d.id&&p.startDate<=(d.endDate||todayStr())&&d.startDate<=periodEffectiveEnd(p))){toast('日期与已有经期重叠，请先核对或补上结束日期');return;}if(d.contactId&&!calInviteRoles().some(c=>c.id===d.contactId)){toast('提醒角色已不可用');return;}const old=S.periods;d.title=String(d.title||'').trim()||'生理期';d.createdAt=d.createdAt||Date.now();if(!periodRecords().some(p=>p.id===d.id))d.owner=owner;S.periods=periodStore().filter(p=>p.id!==d.id).concat(d);_calSaving=true;const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){S.periods=old;toast('保存失败，请重试');return;}_calPeriodDraft=null;_calPanel='periods';render();}
async function calPeriodRemove(id){if(_calSaving||_calPanelOwner!==actId()||!periodRecords().some(p=>p.id===id))return;const state=S,owner=actId(),old=S.periods;_calSaving=true;S.periods=periodStore().filter(p=>p.id!==id);const ok=await calPersist();_calSaving=false;if(S!==state||actId()!==owner)return;if(!ok){S.periods=old;toast('删除失败');return;}_calPeriodDraft=null;_calPanel='periods';render();}
function calPeriodRemoveAsk(id){askConfirm('删除这一段经期记录？',()=>calPeriodRemove(id),{danger:true});}
function calPeriodBack(){if(_calSaving)return;_calPeriodDraft=null;_calPanel=_calPanel==='periodEdit'?'periods':'list';render();}
function renderCalPeriod(){const d=_calPeriodDraft,p=calPrefs(),rows=periodRecords().slice().reverse(),est=periodEstimate(),edit=_calPanel==='periodEdit';const header='<header class="cal-sheet-header"><button class="photo-album-glass cal-sheet-close" aria-label="返回日历管理" onclick="calPeriodBack()">'+calIcon('back')+'</button><strong>'+ (edit?'经期记录':'经期')+'</strong>'+(edit?'<button class="photo-album-glass cal-sheet-close cal-sheet-confirm" aria-label="保存经期记录" onclick="calPeriodSave()">'+calIcon('check')+'</button>':'<span></span>')+'</header>';let body='';if(edit&&d){body='<section class="cal-sheet-group"><input aria-label="经期名称" value="'+calAttr(d.title)+'" oninput="calPeriodField(\'title\',this.value)" maxlength="160"><label class="cal-sheet-row"><span>开始日期</span><input class="cal-integrated-date" aria-label="经期开始日期" type="date" value="'+calAttr(d.startDate)+'" onchange="calPeriodField(\'startDate\',this.value)"></label><label class="cal-sheet-row"><span>结束日期</span><input class="cal-integrated-date" aria-label="经期结束日期" type="date" value="'+calAttr(d.endDate)+'" onchange="calPeriodField(\'endDate\',this.value)"></label></section><p class="cal-sheet-note cal-period-note">结束日期留空表示本次仍在进行；结束后再补准确日期。</p><h3>提醒角色</h3><section class="cal-sheet-group"><label class="cal-sheet-row"><span>记录开始时关心我</span><select aria-label="经期提醒角色" onchange="calPeriodField(\'contactId\',this.value)"><option value="">不指定</option>'+calInviteRoles().map(c=>'<option value="'+calAttr(c.id)+'"'+(d.contactId===c.id?' selected':'')+'>'+esc(c.remark||c.name)+'</option>').join('')+'</select></label></section>'+(rows.some(p=>p.id===d.id)?'<button class="photo-album-glass cal-glass cal-detail-delete" onclick="'+calCall('calPeriodRemoveAsk',d.id)+'">删除记录</button>':'');}else{body='<section class="cal-sheet-group"><div class="cal-sheet-row"><span>显示在日历中</span>'+calSwitch(p.periodVisible!==false,"calPreference('periodVisible')",'显示经期记录')+'</div><div class="cal-sheet-row"><span>经期生活提醒</span>'+calSwitch(p.periodReminders!==false,"calPreference('periodReminders')",'经期生活提醒')+'</div></section><p class="cal-sheet-note cal-period-note">关闭显示只隐藏日期点和当天记录。关闭提醒会停止日历触发的经期关心；记录仍保留。</p><h3>我的记录</h3>'+(rows.length?'<section class="cal-sheet-group">'+rows.map(p=>'<button class="cal-sheet-row" aria-label="查看经期 '+p.startDate+'" onclick="'+calCall('calPeriodOpen',p.id)+'"><i class="cal-color-dot" style="background:#ff5b78"></i><span>'+esc(p.title||'生理期')+'<small>'+esc(p.startDate)+' — '+esc(p.endDate||'进行中')+' · '+(calDayDiff(periodEffectiveEnd(p),p.startDate)+1)+'天</small></span><em class="cal-row-chevron">'+calIcon('chevron')+'</em></button>').join('')+'</section>':'<div class="cal-sheet-empty">还没有经期记录</div>')+'<button class="cal-sheet-group cal-sheet-row cal-add-calendar" onclick="calPeriodNew()">'+calIcon('plus')+'<span>记录本次经期</span></button>'+(est?'<p class="cal-sheet-note cal-period-note">按历史记录估算，下次约在 '+esc(est.date)+' 前后；这只是生活参考。</p>':'');}return '<div class="cal-sheet-page cal-integrated-page">'+header+'<main class="cal-sheet-body">'+body+'</main></div>';}
function calJumpShift(step){const p=calDateParts(_calJumpMonth+'-01'),d=new Date(p.y,p.m-1+step,1);if(d.getFullYear()<1900||d.getFullYear()>2100)return;_calJumpMonth=calDateString(d).slice(0,7);render();}
function calJumpField(year,month){year=+year;month=+month;if(year<1900||year>2100||month<1||month>12)return;_calJumpMonth=year+'-'+String(month).padStart(2,'0');render();}
function calJumpPick(date){if(!roleCalDateValid(date)||_calPanelOwner!==actId())return;_calPanel='';_calDraft=null;_calYearView=false;if(_calDayView)calDayPick(date);else calSelect(date);}
function renderCalJump(){const p=calDateParts(_calJumpMonth+'-01'),offset=(new Date(p.y,p.m-1,1).getDay()+6)%7,days=new Date(p.y,p.m,0).getDate(),cells=Array(offset).fill('<span></span>');for(let day=1;day<=days;day++){const date=_calJumpMonth+'-'+String(day).padStart(2,'0');cells.push('<button class="'+(date===_calSelected?'selected':'')+'" aria-label="跳转到 '+date+'" onclick="'+calCall('calJumpPick',date)+'">'+day+'</button>');}return '<div class="cal-sheet-page cal-integrated-page">'+calColorHeader('跳转到日期')+'<main class="cal-sheet-body"><p class="cal-sheet-note">选择某一天，直接回到该日期的日历。</p><section class="cal-sheet-group cal-jump-picker"><header><button aria-label="上个月" onclick="calJumpShift(-1)">'+calIcon('back')+'</button><input aria-label="跳转年份" type="number" min="1900" max="2100" value="'+p.y+'" onchange="calJumpField(this.value,'+p.m+')"><select aria-label="跳转月份" onchange="calJumpField('+p.y+',this.value)">'+Array.from({length:12},(_,i)=>'<option value="'+(i+1)+'"'+(p.m===i+1?' selected':'')+'>'+(i+1)+'月</option>').join('')+'</select><button aria-label="下个月" onclick="calJumpShift(1)">'+calIcon('chevron')+'</button></header><div class="cal-jump-week">一 二 三 四 五 六 日</div><div class="cal-jump-days">'+cells.join('')+'</div></section></main></div>';}

function calLegacyRecordsOpen(){calPeriodOpen();}

let _calYearView=false,_calYearSelected=null,_calYearCenter=0,_calYearQueued=false,_calYearLoading=false,_calYearFrame=0,_calSwipe=null,_calIgnoreClickUntil=0;
const CAL_YEAR_MIN=1900,CAL_YEAR_MAX=2100;
function calInputClock(){return typeof performance!=='undefined'&&typeof performance.now==='function'?performance.now():Date.now();}
function calOpenYear(){calEnsure();_calDayView=false;_calYearView=true;_calYearCenter=Math.max(CAL_YEAR_MIN,Math.min(CAL_YEAR_MAX,calDateParts(_calMonth+'-01').y));_calYearSelected=_calYearCenter;render();}
function calYearPick(year){if(!Number.isInteger(year)||year<CAL_YEAR_MIN||year>CAL_YEAR_MAX)return;const p=calDateParts(_calSelected),month=p?p.m:1,day=Math.min(p?p.d:1,new Date(year,month,0).getDate());_calYearSelected=year;_calYearCenter=year;_calMonth=year+'-'+String(month).padStart(2,'0');_calSelected=_calMonth+'-'+String(day).padStart(2,'0');render();}
function calYearOpenMonth(year,month,event){if(!_calYearView||!Number.isInteger(year)||year<CAL_YEAR_MIN||year>CAL_YEAR_MAX||month<1||month>12)return;let day=1;const cell=event&&event.target&&event.target.closest('[data-cal-year-date]'),date=cell&&cell.dataset.calYearDate,p=calDateParts(date),old=calDateParts(_calSelected);if(p&&p.y===year&&p.m===month)day=p.d;else if(old&&old.y===year&&old.m===month)day=old.d;_calIgnoreClickUntil=0;_calYearView=false;_calYearSelected=year;calSelect(year+'-'+String(month).padStart(2,'0')+'-'+String(day).padStart(2,'0'));}
function calYearName(year){try{const f=new Intl.DateTimeFormat('zh-CN-u-ca-chinese',{year:'numeric',timeZone:'UTC'}),parts=f.formatToParts(new Date(Date.UTC(year,6,1,12))),name=(parts.find(x=>x.type==='yearName')||{}).value||'',index='子丑寅卯辰巳午未申酉戌亥'.indexOf(name.slice(-1));return name&&index>=0?name+'鼠牛虎兔龙蛇马羊猴鸡狗猪'[index]+'年':'';}catch(_){return '';}}
function calYearMonthHTML(year,month,today){const first=new Date(year,month-1,1),offset=(first.getDay()+6)%7,days=new Date(year,month,0).getDate(),key=year+'-'+String(month).padStart(2,'0'),cells=[],actual=today.slice(0,7)===key,selected=_calYearSelected===year&&_calMonth===key;for(let i=0;i<42;i++){const day=i-offset+1;if(day<1||day>days){cells.push('<span aria-hidden="true"></span>');continue;}const date=key+'-'+String(day).padStart(2,'0'),lunar=calLunarLabel(date);cells.push('<span data-cal-year-date="'+date+'" class="'+(date===today?'cal-mini-today ':'')+(lunar.monthStart?'cal-mini-lunar':'')+'"><b>'+day+'</b></span>');}return '<button class="cal-year-month" data-cal-year-month="'+key+'" aria-label="打开'+year+'年'+month+'月" onclick="calYearOpenMonth('+year+','+month+',event)"><strong class="'+(actual||selected?'cal-year-red':'')+'">'+month+'月</strong><div class="cal-mini-grid">'+cells.join('')+'</div></button>';}
function calYearSection(year){const today=todayStr(),current=calDateParts(today).y===year||_calYearSelected===year,months=[];for(let month=1;month<=12;month++)months.push(calYearMonthHTML(year,month,today));return '<section class="cal-year-section" data-cal-overview-year="'+year+'"><header class="cal-year-heading"><button class="cal-year-title '+(current?'cal-year-red':'')+'" aria-label="选择'+year+'年" onclick="calYearPick('+year+')">'+year+'年</button><div class="cal-year-legend">'+(calYearName(year)?'<span><i></i>'+esc(calYearName(year))+'</span>':'')+'<span><i></i>农历初一</span></div></header><div class="cal-year-months">'+months.join('')+'</div></section>';}
function calQueueYear(){if(typeof document==='undefined'||_calYearQueued)return;_calYearQueued=true;const state=S;queueMicrotask(()=>{_calYearQueued=false;requestAnimationFrame(()=>{if(S!==state||!_calYearView||typeof cur==='function'&&cur().p!=='calendar')return;const box=document.getElementById('cal_year_scroll'),section=box&&box.querySelector('[data-cal-overview-year="'+_calYearCenter+'"]');if(section)box.scrollTop=section.offsetTop;});});}
function calYearScrolled(){if(_calYearFrame)return;_calYearFrame=requestAnimationFrame(()=>{_calYearFrame=0;const box=document.getElementById('cal_year_scroll');if(!box||!_calYearView||_calYearLoading||typeof cur==='function'&&cur().p!=='calendar')return;const children=Array.from(box.children),first=children[0],last=children[children.length-1];if(!first||!last)return;const low=+first.dataset.calOverviewYear,high=+last.dataset.calOverviewYear;_calYearLoading=true;try{if(box.scrollTop<150&&low>CAL_YEAR_MIN){const before=box.scrollHeight,top=box.scrollTop;box.insertAdjacentHTML('afterbegin',calYearSection(low-1));box.scrollTop=top+box.scrollHeight-before;while(box.children.length>5)box.lastElementChild.remove();}else if(box.scrollHeight-box.scrollTop-box.clientHeight<180&&high<CAL_YEAR_MAX){box.insertAdjacentHTML('beforeend',calYearSection(high+1));while(box.children.length>5){const node=box.firstElementChild,height=node.offsetHeight;node.remove();box.scrollTop=Math.max(0,box.scrollTop-height);}}}finally{const visible=Array.from(box.children).filter(node=>node.offsetTop<=box.scrollTop+1).pop()||box.firstElementChild;if(visible)_calYearCenter=+visible.dataset.calOverviewYear;_calYearLoading=false;}});}
function calSwipeStart(event){if(!event.isPrimary||event.button>0)return;_calSwipe={x:event.clientX,y:event.clientY,id:event.pointerId,time:calInputClock(),year:_calYearView,state:S,owner:typeof actId==='function'?actId():''};}
function calSwipeEnd(event){const start=_calSwipe;_calSwipe=null;if(!start||start.id!==event.pointerId||calInputClock()-start.time>1200||start.state!==S||typeof actId==='function'&&start.owner!==actId()||typeof cur==='function'&&cur().p!=='calendar'||start.year!==_calYearView)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;if(Math.abs(dx)<70||Math.abs(dy)>45||Math.abs(dx)<Math.abs(dy)*2)return;if(!start.year&&dx>0){if(event.cancelable)event.preventDefault();_calIgnoreClickUntil=calInputClock()+350;calOpenYear();}else if(start.year&&dx<0){if(event.cancelable)event.preventDefault();_calIgnoreClickUntil=calInputClock()+350;_calYearView=false;render();}}
function renderCalYear(){const center=Math.max(CAL_YEAR_MIN,Math.min(CAL_YEAR_MAX,_calYearCenter||calDateParts(_calMonth+'-01').y)),years=[];for(let year=Math.max(CAL_YEAR_MIN,center-1);year<=Math.min(CAL_YEAR_MAX,center+1);year++)years.push(calYearSection(year));_calYearCenter=center;calQueueYear();return '<div class="cal-month-page cal-years-page" onpointerdown="calSwipeStart(event)" onpointerup="calSwipeEnd(event)" onpointercancel="_calSwipe=null"><header class="cal-reference-nav cal-year-nav">'+calHomeButton()+'<div class="photo-album-glass cal-glass cal-top-actions"><button aria-label="搜索日程" onclick="calSearchOpen()">'+calIcon('search')+'</button><button aria-label="添加日程" onclick="calNewEvent(\''+_calSelected+'\')">'+calIcon('plus')+'</button></div></header><div id="cal_year_scroll" class="cal-year-scroll" onscroll="calYearScrolled()" aria-label="1900年至2100年，可上下滚动">'+years.join('')+'</div><footer class="cal-reference-footer"><button class="photo-album-glass cal-glass cal-today" onclick="calToday()">今天</button><button class="photo-album-glass cal-glass cal-records" aria-label="日历记录管理" onclick="calRecordsOpen()">'+calIcon('calendar')+'</button></footer></div>';}

function renderCalendar(){if(_calPanel)return renderCalPanel();calEnsure();if(_calSearchOpen)return renderCalSearch();if(_calYearView)return renderCalYear();if(_calDayView)return renderCalDay();const p=calDateParts(_calMonth+'-01'),byDate=calEventsByYear(p.y),today=todayStr(),months=[];for(let m=1;m<=12;m++)months.push(calMonthSection(p.y+'-'+String(m).padStart(2,'0'),byDate,today));calQueueMonthScroll();return '<div class="cal-month-page" onpointerdown="calSwipeStart(event)" onpointerup="calSwipeEnd(event)" onpointercancel="_calSwipe=null"><header class="cal-reference-nav"><div class="cal-nav-leading">'+calHomeButton()+'<button class="photo-album-glass cal-glass cal-year" aria-label="查看年总览" onclick="calOpenYear()"><span>'+p.y+'年</span></button></div><div class="photo-album-glass cal-glass cal-top-actions"><button aria-label="搜索日程" onclick="calSearchOpen()">'+calIcon('search')+'</button><button aria-label="添加日程" onclick="calNewEvent(\''+_calSelected+'\')">'+calIcon('plus')+'</button></div></header><div id="cal_month_scroll" class="cal-month-viewport" style="height:'+calMonthHeight(_calMonth)+'px" onscroll="calMonthScrolled()" aria-label="可上下滚动的月份日历">'+months.join('')+'</div><section class="cal-agenda cal-reference-agenda" id="cal_day_agenda" aria-live="polite">'+calAgendaHTML(_calSelected,byDate)+'</section><footer class="cal-reference-footer"><button class="photo-album-glass cal-glass cal-today" onclick="calToday()">今天</button><button class="photo-album-glass cal-glass cal-records" aria-label="日历记录管理" onclick="calRecordsOpen()">'+calIcon('calendar')+'</button></footer></div>';}

function addCalEvent(date,presetType){openModal(`<h3>${presetType==='period'?'记录经期':'添加日程'}</h3>
  <div class="field"><label>日期</label><input id="ce_d" type="date" value="${calDateParts(date)?date:todayStr()}"></div>
  <div class="field"><label>事项</label><input id="ce_t" placeholder="${presetType==='period'?'生理期（可不填）':'去看医生 / 发工资…'}"></div>
  <div class="field"><label>所属日历</label><select id="ce_calendar"><option value="">已有日程</option>${calCollections().map(c=>`<option value="${calAttr(c.id)}">${esc(c.name)}</option>`).join('')}</select></div>
  <div class="field"><label>类型</label><select id="ce_type" onchange="calEventTypeChanged()"><option value="event"${presetType==='period'?'':' selected'}>普通日程</option><option value="reminder">提醒事项</option><option value="period"${presetType==='period'?' selected':''}>姨妈期</option><option value="wedding">预约婚礼</option></select></div>
  <div class="field" id="ce_end_wrap" style="display:${presetType==='period'?'block':'none'}"><label>结束日期（可稍后补）</label><input id="ce_end" type="date" value=""><div class="hint">只填开始日期即可先保存为“进行中”，角色会知道；结束后再补准确日期，角色也会知道实际持续天数。</div></div>
  <div class="field" id="ce_time_field" style="display:none"><label>准确时间</label><input id="ce_time" type="time" value="19:00" step="60"><div class="hint" style="margin-top:7px">保存后只记录约定，不会提前发卡；到了这个日期和时间，角色才会主动发来婚礼形式选择卡。</div></div>
  <div class="field"><label>谁提醒我</label><select id="ce_c"><option value="">不提醒</option>${S.contacts.filter(c=>!c.deleted).map(c=>`<option value="${c.id}">${esc(c.remark||c.name)}</option>`).join('')}</select></div>
  <div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="saveCalEvent()">保存</button></div>`);}
function calEventTypeChanged(){const typeEl=$('#ce_type'),wrap=$('#ce_end_wrap'),timeField=$('#ce_time_field'),title=$('#ce_t'),role=$('#ce_c'),coupleCid=S.couple&&S.couple.cid||'';if(!typeEl)return;const type=typeEl.value,collection=$('#ce_calendar');if(collection)collection.disabled=type==='period';if(wrap)wrap.style.display=type==='period'?'block':'none';if(timeField)timeField.style.display=type==='wedding'?'block':'none';if(title&&type==='wedding'&&!title.value.trim())title.value='我们的婚礼';if(role){if(type==='wedding'){role.value=coupleCid;role.disabled=true;if(!coupleCid)toast('请先在情侣空间绑定婚礼角色');}else role.disabled=false;}}
function saveCalEvent(){const d=$('#ce_d').value,t=$('#ce_t').value.trim(),type=$('#ce_type').value,cid=$('#ce_c').value,time=type==='wedding'?($('#ce_time')&&$('#ce_time').value||''):'';if(!d){toast('请选择日期');return;}if(type==='period'){const end=(($('#ce_end')||{}).value||'').trim();if(end&&(!calDateParts(end)||calDayDiff(end,d)<0)){toast('结束日期不能早于开始日期');return;}periodStore().push({id:uid(),startDate:d,endDate:end,title:t||'生理期',contactId:cid,createdAt:Date.now()});save();closeModal();render();toast(end?'经期开始和结束日期已记录，角色也会知道':'经期开始日期已记录，角色会知道本次正在进行');return;}if(!t){toast('填写事项');return;}if(type==='wedding'&&(!S.couple||!S.couple.cid||cid!==S.couple.cid)){toast('婚礼只能与情侣空间绑定的角色进行');return;}if(type==='wedding'&&!time){toast('预约婚礼需要准确时间');return;}const eventAt=type==='wedding'?new Date(d+'T'+time+':00').getTime():0;if(type==='wedding'&&!Number.isFinite(eventAt)){toast('婚礼日期或时间不正确');return;}
  const calendarId=($('#ce_calendar')||{}).value||'',collection=calendarId&&calCollection(calendarId);if(calendarId&&!collection){toast('日历不可用');return;}if(collection&&cid&&!collection.sharedWith.includes(cid)){toast('请先将该日历共享给提醒角色');return;}const e={id:uid(),date:d,title:t,type,contactId:cid};if(collection)e.calendarId=calendarId;if(type==='wedding'){e.time=time;e.eventAt=eventAt;e.weddingStyle='choice';}S.calendar.push(e);save();if(type==='wedding'&&calEventAlerts(e)&&typeof weddingScheduleCalendarEvent==='function')weddingScheduleCalendarEvent(e);closeModal();render();toast(type==='wedding'?'婚礼日期已约定；到时角色会主动发来邀请卡':'已添加 📅');}
let _calBusy={};
function calendarDeliver(key,today,job){if((S._calFired&&S._calFired[key]===today)||_calBusy[key])return false;_calBusy[key]=1;Promise.resolve().then(job).then(ok=>{if(ok){S._calFired=S._calFired||{};S._calFired[key]=today;save();}}).catch(()=>{}).finally(()=>{delete _calBusy[key];});return true;}
function coupleGoalReminder(c,g,today){if(roleOnlineProactiveBlocked(c.id)||coupleGoalDone(g,today))return Promise.resolve(false);return new Promise(resolve=>{let settled=false;const done=ok=>{if(settled)return;settled=true;resolve(!!ok);};const note=featureEventNote('共同目标每日监督','今天是'+today+'，现在已到你们共同目标「'+g.title+'」约定的监督时间 '+(g.time||'20:00')+'。'+S.me.name+'今天尚未把它标记完成；请结合最近聊天和你本人性格自然提醒一次，可以询问进度、陪ta开始或适度督促，但不要像闹钟或系统通知。今天成功发出这一轮后不要再次提醒；不能重新回答已经回复过的旧句。');const queued=scheduleFeatureReply(c.id,note,120,done);if(!queued)done(false);});}
function periodForecastReminder(c,est){if(calPrefs().periodReminders===false)return Promise.resolve(false);if(!c||c.blocked||roleOnlineProactiveBlocked(c.id))return Promise.resolve(false);return new Promise(resolve=>{let settled=false;const done=ok=>{if(settled)return;settled=true;resolve(!!ok);};const note=featureEventNote('经期临近生活提醒','根据'+S.me.name+'亲自记录的历史经期，下一次大约在 '+est.date+' 前后，今天距离这个估计日期还有 '+Math.max(0,calDayDiff(est.date,todayStr()))+' 天。请按你本人性格生成一条自然、体贴的生活提醒，可以提醒提前准备用品、注意休息或询问身体感受；必须说清只是按记录估计，不要诊断，不要说成确定会在某天来，也不要反复提醒。');const queued=scheduleFeatureReply(c.id,note,120,done);if(!queued)done(false);});}
function checkCalendar(){calFireEventAlerts();calFireInvitedReminders();calFireCalendarCare();if(typeof weddingCalendarTick==='function')(S.calendar||[]).filter(e=>e&&e.type==='wedding'&&calEventAlerts(e)).forEach(e=>weddingCalendarTick(e));if(offlineFocusActive())return;if(!S._calFired)S._calFired={};const F=S._calFired;const today=todayStr(),now=new Date(),h=now.getHours(),nowTime=String(h).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0'),coupleCid=S.couple&&S.couple.cid||'',coupleRole=coupleCid&&getC(coupleCid);if(coupleRole&&!coupleRole.blocked)coupleGoalStore().forEach(g=>{const key=coupleGoalKey(g,today);if(coupleGoalActive(g,today)&&!coupleGoalDone(g,today)&&String(g.time||'20:00')<=nowTime&&F[key]!==today)calendarDeliver(key,today,()=>coupleGoalReminder(coupleRole,g,today));});/* BIRTHDAY_ONLINE_V1（2026-10-30 她说生日当天角色不主动发，要她先开口才祝福）：以前要角色开着主动消息、要过早上 9 点、角色不在忙才发。现在情侣角色不看主动消息开关，7 点半以后、打开 App 或切回前台就检查，忙也照样发；每个角色当天只发一次。 */if(typeof birthdayCareTick==='function')birthdayCareTick(today,now,F);if(h<9)return;
  if(calPrefs().periodReminders!==false)periodRecords().filter(p=>p.startDate===today&&p.contactId).forEach(p=>{const c=getC(p.contactId),key='period_start_'+p.id+'_'+p.startDate;if(c&&!c.deleted&&!c.blocked&&F[key]!==today)calendarDeliver(key,today,()=>remindEvent(c.id,{title:'经期开始：'+(p.title||'生理期'),date:p.startDate,type:'period'}));});
  const hol=holidayOf(today);
  S.contacts.forEach(c=>{if(c.deleted||c.blocked)return;
    /* 过节只有情侣角色会主动来祝福，其他角色不打扰（v1408） */
  });
  S.calendar.forEach(e=>{if(e.editorVersion!==1&&calEventAlerts(e)&&!e.completed&&e.type!=='wedding'&&e.date===today&&e.contactId&&F[e.id]!==today){const c=getC(e.contactId);if(c&&!c.blocked)calendarDeliver(e.id,today,()=>remindEvent(e.contactId,e));}});
  if(coupleCid){const c=getC(coupleCid);if(c&&!c.blocked){if(hol&&F['gift_hol_'+coupleCid]!==today&&holidayCareWindow(hol,now))calendarDeliver('gift_hol_'+coupleCid,today,()=>holidayCare(coupleCid,hol,today));const md=today.slice(5);(S.couple.anniversaries||[]).forEach((a,i)=>{if(a.date.slice(5)===md&&F['anniv_'+i]!==today&&holidayCareWindow(/生日/.test(a.title)?'生日':'纪念日',now))calendarDeliver('anniv_'+i,today,()=>/生日/.test(a.title)?holidayCare(coupleCid,a.title,today,{birthday:true}):occasionGift(coupleCid,'你们的纪念日「'+a.title+'」',today));});const est=periodEstimate(),until=est?calDayDiff(est.date,today):NaN,pkey=est?'period_forecast_'+coupleCid+'_'+est.date:'';if(calPrefs().periodReminders!==false&&est&&until>=0&&until<=3&&!F[pkey])calendarDeliver(pkey,today,()=>periodForecastReminder(c,est));}}
}

//@@ web
setInterval(checkCalendar,60000);setTimeout(checkCalendar,4000);if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(checkCalendar,1500);});
