setInterval(()=>northNativeBackgroundTask('calendar',checkCalendar),60000);setTimeout(()=>northNativeBackgroundTask('calendar',checkCalendar),4000);if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(()=>northNativeBackgroundTask('calendar',checkCalendar),1500);});
